"use client";

import { useEffect, useState } from "react";
import { XP_UPDATED_EVENT } from "@/lib/xpEvent";

interface ProgressStats {
  level: number;
  xpIntoLevel: number;
  xpForNextLevel: number;
  totalXp: number;
  currentStreak: number;
  longestStreak: number;
}

// Always-mounted level/XP bar and daily streak counter — a small layer of
// gamification over the existing spaced-repetition review system. XP itself
// has no separate storage; it's derived from review_log, so this component
// is purely a read+display of /api/xp, refetched on every graded card via
// a lightweight custom event rather than polling.
export default function XpBar() {
  const [stats, setStats] = useState<ProgressStats | null>(null);

  const refresh = () => {
    fetch("/api/xp")
      .then((r) => r.json())
      .then(setStats)
      .catch(() => {});
  };

  useEffect(() => {
    refresh();
    window.addEventListener(XP_UPDATED_EVENT, refresh);
    return () => window.removeEventListener(XP_UPDATED_EVENT, refresh);
  }, []);

  if (!stats) return null;

  const pct = Math.min(100, Math.round((stats.xpIntoLevel / stats.xpForNextLevel) * 100));

  return (
    <div className="flex items-center gap-3">
      <div className="flex items-center gap-2">
        <span className="rounded-full border border-accent-700/60 bg-[#28262a] px-2 py-0.5 text-[10px] font-semibold text-accent-300">
          Lvl {stats.level}
        </span>
        <div className="h-1.5 w-24 overflow-hidden rounded-full bg-[#322f33]" title={`${stats.xpIntoLevel} / ${stats.xpForNextLevel} XP`}>
          <div className="h-full rounded-full bg-accent-400" style={{ width: `${pct}%` }} />
        </div>
      </div>
      {stats.currentStreak > 0 && (
        <span
          className="rounded-full border border-[#423e42] bg-[#28262a] px-2 py-0.5 text-[10px] font-medium text-[#8F8978]"
          title={`Longest streak: ${stats.longestStreak} day${stats.longestStreak > 1 ? "s" : ""}`}
        >
          Streak {stats.currentStreak}d
        </span>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useReview } from "@/lib/useReview";
import ReviewIntervals from "@/components/ReviewIntervals";
import { useStudyQueue } from "@/lib/useStudySession";
import type { VocabularyCard } from "@/lib/db";
import type { Grade } from "@/lib/srs";
import { notifyXpUpdated } from "@/lib/xpEvent";
import { useCardShortcuts } from "@/lib/useCardShortcuts";

interface DueVocabularyCard {
  card: VocabularyCard;
  isNew: boolean;
}

interface VocabTabProps {
  initialCards: DueVocabularyCard[];
}

const GRADE_OPTIONS: Array<{ grade: Grade; label: string; hint: string; className: string }> = [
  { grade: "again", label: "Again", hint: "didn't know it", className: "bg-red-500/20 border-red-500/40 text-red-200 hover:bg-red-500/30" },
  { grade: "hard", label: "Hard", hint: "struggled", className: "bg-amber-500/20 border-amber-500/40 text-amber-200 hover:bg-amber-500/30" },
  { grade: "good", label: "Good", hint: "got it", className: "bg-emerald-500/20 border-emerald-500/40 text-emerald-200 hover:bg-emerald-500/30" },
  { grade: "easy", label: "Easy", hint: "trivial", className: "bg-accent-500/20 border-accent-500/40 text-accent-200 hover:bg-accent-500/30" },
];

export default function VocabTab({ initialCards }: VocabTabProps) {
  const { cards, setCards, index, setIndex, revealed, setRevealed, sessionDone, setSessionDone, reviewedCount, setReviewedCount } = useStudyQueue("vocab", initialCards);
  const saveReview=useReview("vocab");
  const [grading, setGrading] = useState(false);
  const [gradeError, setGradeError] = useState<string | null>(null);

  const current = cards[index];

  const grade = async (g: Grade) => {
    if (!current || grading) return;
    setGrading(true);
    setGradeError(null);
    try {
      const res = await saveReview("vocabulary", current.card.id, g);
      if (!res.ok) throw new Error("Your review could not be saved. Please try again.");
      notifyXpUpdated();
      setReviewedCount((n) => n + 1);
      if (index + 1 >= cards.length) {
        setSessionDone(true);
      } else {
        setIndex((i) => i + 1);
        setRevealed(false);
      }
    } catch (error) {
      setGradeError(error instanceof Error ? error.message : "Your review could not be saved. Please try again.");
    } finally {
      setGrading(false);
    }
  };

  const restart = async () => {
    const res = await fetch("/api/vocabulary/queue");
    if (res.ok) {
      const data = await res.json();
      setCards(data.cards);
      setIndex(0);
      setRevealed(false);
      setReviewedCount(0);
      setSessionDone(data.cards.length === 0);
    }
  };

  useCardShortcuts({
    revealed,
    onReveal: () => setRevealed(true),
    onGrade: grade,
    disabled: grading || sessionDone || !current,
  });

  if (sessionDone) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-4 text-center">
        <p className="text-lg text-[#D4C6A6]">
          {reviewedCount > 0
            ? `Session done — ${reviewedCount} expression${reviewedCount > 1 ? "s" : ""} reviewed.`
            : "No vocabulary due. Select any English text in the app and press Alt+2 to add one."}
        </p>
        <p className="max-w-sm text-sm text-[#696A61]">
          Same spaced-repetition schedule as the rest of the app, applied to expressions you capture while
          reading.
        </p>
        <button
          onClick={restart}
          className="rounded-md border border-[#423e42] bg-[#28262a] px-4 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33]"
        >
          Check again
        </button>
      </div>
    );
  }

  return (
    <div className="mx-auto flex h-full max-w-2xl flex-col justify-center gap-6 px-6 py-10">
      {gradeError && <p role="alert" className="text-sm text-red-400">{gradeError}</p>}
      {revealed && <ReviewIntervals type="vocabulary" id={current.card.id}/>}
      <div className="flex items-center justify-between text-xs text-[#696A61]">
        <span>
          Card {index + 1} / {cards.length}
        </span>
        {current.isNew && <span className="text-accent-400">new</span>}
      </div>

      <div className="rounded-lg border border-[#423e42] bg-[#201f21] p-6">
        <p className="text-lg font-medium text-[#D4C6A6]">{current.card.phrase}</p>

        {revealed ? (
          <div className="mt-4 space-y-2 border-t border-[#423e42] pt-4">
            <p className="text-base text-accent-200">{current.card.translationFr}</p>
            {current.card.example && (
              <p className="text-sm italic text-[#8F8978]">&ldquo;{current.card.example}&rdquo;</p>
            )}
            {current.card.note && <p className="text-xs text-[#696A61]">{current.card.note}</p>}
          </div>
        ) : (
          <div className="mt-4 rounded-md border border-dashed border-white/10 bg-[#201f21] p-3 text-center text-sm text-[#696A61]">
            •••
          </div>
        )}
      </div>

      {!revealed ? (
        <button
          onClick={() => setRevealed(true)}
          className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829]"
        >
          Reveal <span className="text-[#696A61]">(space)</span>
        </button>
      ) : (
        <div className="grid grid-cols-4 gap-2">
          {GRADE_OPTIONS.map((opt, idx) => (
            <button
              key={opt.grade}
              onClick={() => grade(opt.grade)}
              disabled={grading}
              title={opt.hint}
              className={`rounded-md border px-3 py-2.5 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50 ${opt.className}`}
            >
              {opt.label} <span className="opacity-60">{idx + 1}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";

interface Toast {
  kind: "success" | "error";
  message: string;
}

// Global Alt+1 / Alt+2 listener: select any English text anywhere in the
// app and press Alt+1 to send it to Pronounce, or Alt+2 to save it as a
// translated Vocab card. Mounted once in the root layout so it works
// everywhere, not just one page.
export default function VocabCapture() {
  const [toast, setToast] = useState<Toast | null>(null);
  const [capturing, setCapturing] = useState<"vocab" | "pronounce" | null>(null);

  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 4000);
    return () => clearTimeout(t);
  }, [toast]);

  useEffect(() => {
    const onKeyDown = async (e: KeyboardEvent) => {
      if (!e.altKey || (e.key !== "1" && e.key !== "2")) return;
      const mode = e.key === "1" ? "pronounce" : "vocab";

      const selection = window.getSelection()?.toString().trim() ?? "";
      if (selection.length === 0) {
        setToast({ kind: "error", message: `Select some text first, then press Alt+${e.key}.` });
        return;
      }
      const maxLength = mode === "pronounce" ? 2000 : 300;
      if (selection.length > maxLength) {
        setToast({
          kind: "error",
          message:
            mode === "pronounce"
              ? "Select a shorter passage (a paragraph or less)."
              : "Select a shorter phrase (not a whole paragraph).",
        });
        return;
      }

      e.preventDefault();
      setCapturing(mode);
      try {
        const res = await fetch(mode === "pronounce" ? "/api/pronunciation/generate" : "/api/vocabulary/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ text: selection }),
        });
        const data = await res.json();
        if (!res.ok) {
          setToast({
            kind: "error",
            message: data.error ?? `Could not save this ${mode === "pronounce" ? "passage" : "expression"}.`,
          });
          return;
        }
        setToast(
          mode === "pronounce"
            ? { kind: "success", message: "Added to Pronounce." }
            : { kind: "success", message: `Added to Vocab: "${data.card.phrase}" → "${data.card.translationFr}"` }
        );
      } catch {
        setToast({ kind: "error", message: "Network error while saving." });
      } finally {
        setCapturing(null);
      }
    };

    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  if (!toast && !capturing) return null;

  return (
    <div
      className={
        capturing
          ? "fixed bottom-5 right-5 z-[100] rounded-md border border-[#423e42] bg-[#201f21] px-4 py-2.5 text-sm text-[#8F8978] shadow-2xl"
          : `fixed bottom-5 right-5 z-[100] max-w-sm rounded-md border px-4 py-2.5 text-sm shadow-2xl ${
              toast?.kind === "success"
                ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-200"
                : "border-amber-500/30 bg-amber-500/10 text-amber-200"
            }`
      }
    >
      {capturing ? (capturing === "pronounce" ? "Breaking down…" : "Translating…") : toast?.message}
    </div>
  );
}

"use client";
import {useContext,useState} from 'react';
import {useRouter} from 'next/navigation';
import { StudySessionContext,useStudyState } from '@/lib/useStudySession';
import {useCourseFetch} from '@/lib/useCourseFetch';
import type { Notion } from '@/lib/types';
import ClairReader from '@/components/ClairReader';
import type {ClairLesson} from '@/lib/clair';

export default function UnderstandTab({allNotions}: {allNotions: Notion[]}) {
  const {courseId}=useContext(StudySessionContext),fetch=useCourseFetch(courseId),router=useRouter();
  const topics = allNotions.filter(n => n.layer !== 'organizer');
  const [selected, setSelected] = useStudyState('understand-topic', '', value => typeof value === 'string' ? value : null);
  const [lessons,setLessons]=useState<Record<string,{lesson:ClairLesson;baseline:string}>>({});
  const [pending,setPending]=useState<string[]>([]),[errors,setErrors]=useState<Record<string,string>>({});
  const index = Math.max(0, topics.findIndex(n => n.id === selected)), notion = topics[index];
  if (!notion) return <p className="p-6 text-sm text-[#8F8978]">Import a course PDF and generate its learning map to begin.</p>;
  const baseline=JSON.stringify([notion.label,notion.definition,notion.explanation,notion.sources]);
  const lesson=(lessons[notion.id]?.baseline===baseline?lessons[notion.id].lesson:undefined)??notion.clair;
  const deepen=async()=>{
    const id=notion.id;if(pending.includes(id))return;
    setPending(p=>[...p,id]);setErrors(e=>({...e,[id]:''}));
    try{
      const response=await fetch(`/api/notions/${encodeURIComponent(id)}/lesson`,{method:'POST'}),body=await response.json();
      if(!response.ok)throw new Error(body.error??'Could not deepen this concept');
      setLessons(l=>({...l,[id]:{lesson:body.lesson,baseline}}));router.refresh();
    }catch(error){setErrors(e=>({...e,[id]:error instanceof Error?error.message:'Could not deepen this concept'}));}
    finally{setPending(p=>p.filter(v=>v!==id));}
  };
  return <div className="mx-auto max-w-2xl space-y-4 px-6 py-8">
    <div className="flex items-center gap-3">
      <label htmlFor="understand-topic" className="text-xs text-[#696A61]">Course path</label>
      <select id="understand-topic" value={notion.id} onChange={e => setSelected(e.target.value)} className="min-w-0 flex-1 rounded border border-[#423e42] bg-[#28262a] p-2 text-sm text-[#D4C6A6]">{topics.map(n => <option key={n.id} value={n.id}>{n.label}</option>)}</select>
    </div>
    <h2 className="text-base font-semibold text-[#D4C6A6]">{notion.label}</h2>
    {lesson ? <ClairReader key={notion.id} lesson={lesson} onSelect={setSelected}/> : <>
      <p className="text-xs text-[#696A61]">Existing notes are preserved. Open a source slide to check the explanation.</p>
      <p className="whitespace-pre-line text-sm leading-relaxed text-[#8F8978]">{notion.explanation || notion.definition}</p>
      {notion.sources.map(s => <a key={`${s.documentId}:${s.page}`} className="mr-3 text-xs text-accent-400" href={`/api/documents/${encodeURIComponent(s.documentId)}/file#page=${s.page}`} target="_blank" rel="noreferrer">Slide {s.page} ↗</a>)}
    </>}
    {(!lesson||lesson.depth==='overview')&&!notion.userEdited&&notion.status!=='validated'&&notion.evidence?.some(s=>s.quote)&&<div className="space-y-2">
      <button onClick={deepen} disabled={pending.includes(notion.id)} className="rounded border border-[#423e42] px-3 py-2 text-xs text-accent-400 disabled:opacity-50">{pending.includes(notion.id)?'Deepening this concept…':'Deepen understanding'}</button>
      <p className="text-xs text-[#696A61]">The current lesson is ready to study. Deepen it for more intuition and varied practice.</p>
    </div>}
    {errors[notion.id]&&<p role="alert" className="text-xs text-red-400">{errors[notion.id]}</p>}
    <div className="flex justify-between text-xs text-[#8F8978]">
      <button disabled={index === 0} onClick={() => setSelected(topics[index - 1].id)} className="disabled:opacity-30">← Previous concept</button>
      <button disabled={index + 1 === topics.length} onClick={() => setSelected(topics[index + 1].id)} className="disabled:opacity-30">Next concept →</button>
    </div>
  </div>;
}

"use client";

import { useState } from "react";
import { useReview } from "@/lib/useReview";
import ReviewIntervals from "@/components/ReviewIntervals";
import { useStudyQueue } from "@/lib/useStudySession";
import { colorForDomain } from "@/lib/types";
import type { Grade } from "@/lib/srs";
import { notifyXpUpdated } from "@/lib/xpEvent";
import { useCardShortcuts } from "@/lib/useCardShortcuts";
import type { TodayCard } from "@/lib/today";
import { NotionPill, Connector } from "@/components/ConnectTab";
import { WordCell, LinkedPair, groupLinkedWords } from "@/components/PronounceTab";

interface TodayTabProps {
  initialCards: TodayCard[];
}

const GRADE_OPTIONS: Array<{ grade: Grade; label: string; hint: string; className: string }> = [
  { grade: "again", label: "Again", hint: "didn't know it", className: "bg-red-500/20 border-red-500/40 text-red-200 hover:bg-red-500/30" },
  { grade: "hard", label: "Hard", hint: "struggled", className: "bg-amber-500/20 border-amber-500/40 text-amber-200 hover:bg-amber-500/30" },
  { grade: "good", label: "Good", hint: "got it", className: "bg-emerald-500/20 border-emerald-500/40 text-emerald-200 hover:bg-emerald-500/30" },
  { grade: "easy", label: "Easy", hint: "trivial", className: "bg-accent-500/20 border-accent-500/40 text-accent-200 hover:bg-accent-500/30" },
];

const KIND_LABELS: Record<TodayCard["kind"], string> = {
  notion: "Drill",
  link: "Connect",
  pronunciation: "Pronounce",
  vocabulary: "Vocab",
};

function cardId(card: TodayCard): string {
  if (card.kind === "notion") return card.cardId ?? card.notion.id;
  if (card.kind === "link") return card.cardId ?? card.link.id;
  return card.card.id;
}

// A mixed, interleaved queue across every due card type (notion/link/
// pronunciation/vocabulary) — the "what's due today" session. Interleaving
// different card types in one sitting is a well-studied retention booster
// over blocking by type, which is why Drill/Connect/Pronounce/Vocab still
// exist separately for generating and managing cards, but reviewing them
// one type at a time isn't the default anymore.
export default function TodayTab({ initialCards }: TodayTabProps) {
  const { cards, setCards, index, setIndex, revealed, setRevealed, sessionDone, setSessionDone, reviewedCount, setReviewedCount } = useStudyQueue("today", initialCards);
  const saveReview=useReview("today");
  const [grading, setGrading] = useState(false);
  const [gradeError, setGradeError] = useState<string | null>(null);

  const current = cards[index];

  const grade = async (g: Grade) => {
    if (!current || grading) return;
    setGrading(true);
    setGradeError(null);
    try {
      const res = await saveReview(current.kind, cardId(current), g);
      if (!res.ok) throw new Error("Your review could not be saved. Please try again.");
      notifyXpUpdated();
      setReviewedCount((n) => n + 1);
      if (index + 1 >= cards.length) {
        setSessionDone(true);
      } else {
        setIndex((i) => i + 1);
        setRevealed(false);
      }
    } catch (error) {
      setGradeError(error instanceof Error ? error.message : "Your review could not be saved. Please try again.");
    } finally {
      setGrading(false);
    }
  };

  const restart = async () => {
    const res = await fetch("/api/review/today");
    if (res.ok) {
      const data = await res.json();
      setCards(data.cards);
      setIndex(0);
      setRevealed(false);
      setReviewedCount(0);
      setSessionDone(data.cards.length === 0);
    }
  };

  useCardShortcuts({
    revealed,
    onReveal: () => setRevealed(true),
    onGrade: grade,
    disabled: grading || sessionDone || !current,
  });

  if (sessionDone) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-4 text-center">
        <p className="text-lg text-[#D4C6A6]">
          {reviewedCount > 0
            ? `Session done — ${reviewedCount} card${reviewedCount > 1 ? "s" : ""} reviewed.`
            : "Nothing due right now."}
        </p>
        <p className="max-w-sm text-sm text-[#696A61]">
          Every due card — Drill, Connect, Pronounce, and Vocab — mixed into one interleaved session instead
          of one type at a time.
        </p>
        <button
          onClick={restart}
          className="rounded-md border border-[#423e42] bg-[#28262a] px-4 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33]"
        >
          Check again
        </button>
      </div>
    );
  }

  return (
    <div className="mx-auto flex h-full max-w-2xl flex-col justify-center gap-6 px-6 py-10">
      {gradeError && <p role="alert" className="text-sm text-red-400">{gradeError}</p>}
      {revealed && <ReviewIntervals type={current.kind} id={cardId(current)}/>}
      <div className="flex items-center justify-between text-xs text-[#696A61]">
        <span>
          Card {index + 1} / {cards.length}
        </span>
        <span className="flex items-center gap-2">
          {current.isNew && <span className="text-accent-400">new</span>}
          <span className="rounded-full border border-[#423e42] bg-[#28262a] px-2 py-0.5 text-[10px] uppercase tracking-wide text-[#696A61]">
            {KIND_LABELS[current.kind]}
          </span>
        </span>
      </div>

      <div className="rounded-lg border border-[#423e42] bg-[#201f21] p-6">
        {current.kind === "notion" && (
          <>
            <div className="mb-4 flex items-center gap-2">
              <span
                className="rounded-full px-2 py-0.5 text-xs font-medium text-white"
                style={{ backgroundColor: colorForDomain(current.notion.domain) }}
              >
                {current.notion.domain}
              </span>
              <h2 className="text-base font-semibold text-[#D4C6A6]">{current.notion.label}</h2>
            </div>
            {!revealed ? (
              <p className="text-sm italic text-[#696A61]">{current.question ?? "Recall the definition, then reveal."}</p>
            ) : (
              <div className="space-y-3">
                <p className="text-sm leading-relaxed text-[#D4C6A6]">{current.card.definition}</p>
                {current.card.example && (
                  <p className="text-sm leading-relaxed text-[#8F8978]">
                    <span className="font-medium text-[#696A61]">Example: </span>
                    {current.card.example}
                  </p>
                )}
              </div>
            )}
          </>
        )}

        {current.kind === "link" && (
          <>
            <div className="mb-6 flex items-center gap-2">
              <NotionPill label={current.source.label} domain={current.source.domain} />
              <Connector type={current.link.type} color={colorForDomain(current.source.domain)} />
              <NotionPill label={current.target.label} domain={current.target.domain} />
            </div>
            <p className="mb-3 text-center text-xs uppercase tracking-wide text-[#696A61]">
              How are these connected?
            </p>
            {revealed ? (
              <p className="rounded-md bg-accent-500/10 p-3 text-sm leading-relaxed text-[#8F8978]">
                {current.link.description}
              </p>
            ) : (
              <div className="rounded-md border border-dashed border-white/10 bg-[#201f21] p-3 text-center text-sm text-[#696A61]">
                •••
              </div>
            )}
          </>
        )}

        {current.kind === "pronunciation" && (
          <>
            {!revealed ? (
              <p className="text-base leading-relaxed text-[#8F8978]">{current.card.text}</p>
            ) : (
              <>
                {current.card.fullIpa && (
                  <p className="mb-4 border-b border-[#423e42] pb-3 text-center text-sm text-accent-200">
                    {current.card.fullIpa}
                  </p>
                )}
                <p className="flex flex-wrap items-start gap-x-3 gap-y-4 text-base leading-relaxed">
                  {groupLinkedWords(current.card.words).map((group, i) =>
                    group.length === 2 ? (
                      <LinkedPair key={i} words={group as [typeof group[0], typeof group[0]]} />
                    ) : (
                      <WordCell key={i} word={group[0]} />
                    )
                  )}
                </p>
              </>
            )}
          </>
        )}

        {current.kind === "vocabulary" && (
          <>
            <p className="text-lg font-medium text-[#D4C6A6]">{current.card.phrase}</p>
            {revealed ? (
              <div className="mt-4 space-y-2 border-t border-[#423e42] pt-4">
                <p className="text-base text-accent-200">{current.card.translationFr}</p>
                {current.card.example && (
                  <p className="text-sm italic text-[#8F8978]">&ldquo;{current.card.example}&rdquo;</p>
                )}
                {current.card.note && <p className="text-xs text-[#696A61]">{current.card.note}</p>}
              </div>
            ) : (
              <div className="mt-4 rounded-md border border-dashed border-white/10 bg-[#201f21] p-3 text-center text-sm text-[#696A61]">
                •••
              </div>
            )}
          </>
        )}
      </div>

      {!revealed ? (
        <button
          onClick={() => setRevealed(true)}
          className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829]"
        >
          Reveal <span className="text-[#696A61]">(space)</span>
        </button>
      ) : (
        <div className="grid grid-cols-4 gap-2">
          {GRADE_OPTIONS.map((opt, idx) => (
            <button
              key={opt.grade}
              onClick={() => grade(opt.grade)}
              disabled={grading}
              title={opt.hint}
              className={`rounded-md border px-3 py-2.5 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50 ${opt.className}`}
            >
              {opt.label} <span className="opacity-60">{idx + 1}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { Activity, useMemo, useState } from "react";
import { StudySessionContext, useStudyState } from "@/lib/useStudySession";
import Link from "next/link";
import type { DrillCard, Notion } from "@/lib/types";
import type { DueLink as DueLinkCard, PronunciationCard, VocabularyCard } from "@/lib/db";
import type { TodayCard } from "@/lib/today";
import DrillTab from "@/components/DrillTab";
import ExplainTab from "@/components/ExplainTab";
import ConnectTab from "@/components/ConnectTab";
import PronounceTab from "@/components/PronounceTab";
import VocabTab from "@/components/VocabTab";
import TodayTab from "@/components/TodayTab";
import UnderstandTab from '@/components/UnderstandTab';

export interface DueCard {
  cardId?: string;
  question?: string;
  notion: Notion;
  isNew: boolean;
  card: DrillCard;
}

export type DueLink = DueLinkCard;

export interface DuePronunciationCard {
  card: PronunciationCard;
  isNew: boolean;
}

export interface DueVocabularyCard {
  card: VocabularyCard;
  isNew: boolean;
}

interface StudyClientProps {
  courseId: string;
  validCardKeys: string[];
  initialCards: DueCard[];
  initialLinkCards: DueLink[];
  initialPronunciationCards: DuePronunciationCard[];
  initialVocabularyCards: DueVocabularyCard[];
  initialTodayCards: TodayCard[];
  allNotions: Notion[];
  llmConfigured: boolean;
}

type Tab = "understand" | "today" | "drill" | "connect" | "explain" | "pronounce" | "vocab";

const TAB_LABELS: Record<Tab, string> = {
  understand: 'Understand',
  today: "Today",
  drill: "Drill",
  connect: "Connect",
  explain: "Explain",
  pronounce: "Pronounce",
  vocab: "Vocab",
};

export default function StudyClient({
  courseId,
  validCardKeys,
  ...props
}: StudyClientProps) {
  const context = useMemo(() => ({ courseId, validCardKeys: new Set(validCardKeys) }), [courseId, validCardKeys]);
  return (
    <StudySessionContext.Provider value={context}>
      <StudyTabs {...props} />
    </StudySessionContext.Provider>
  );
}

const restoreTab = (value: unknown): Tab | null => typeof value === "string" && Object.hasOwn(TAB_LABELS, value) ? value as Tab : null;

function StudyTabs({
  initialCards,
  initialLinkCards,
  initialPronunciationCards,
  initialVocabularyCards,
  initialTodayCards,
  allNotions,
  llmConfigured,
}: Omit<StudyClientProps, "courseId" | "validCardKeys">) {
  const [tab, setTab] = useStudyState<Tab>("tab", allNotions.some(n => n.clair) ? 'understand' : 'today', restoreTab);
  const [pendingPronunciationCard, setPendingPronunciationCard] = useState<PronunciationCard | null>(null);

  const practicePronunciation = (card: PronunciationCard) => {
    setPendingPronunciationCard(card);
    setTab("pronounce");
  };

  return (
    <div className="flex h-full flex-col bg-[#1a1a1b]">
      <header className="flex items-center justify-between gap-4 border-b border-[#423e42] bg-[#201f21] px-5 py-3">
        <div className="flex items-center gap-4">
          <Link href="/" className="text-xs text-[#696A61] hover:text-[#8F8978]">
            ← Back to graph
          </Link>
          <h1 className="text-base font-semibold tracking-tight text-[#D4C6A6]">Study</h1>
        </div>
        <div className="flex items-center gap-2">
          <Link href="/browse" className="text-xs text-[#696A61] hover:text-[#8F8978]">
            Browse →
          </Link>
          <Link
            href="/progress"
            className="text-xs text-[#696A61] hover:text-[#8F8978]"
          >
            Progress →
          </Link>
          <div className="flex border border-[#423e42] bg-[#28262a] p-0.5 text-xs">
            {(["understand", "today", "drill", "connect", "explain", "pronounce", "vocab"] as const).map((t) => (
              <button
                key={t}
                onClick={() => setTab(t)}
                className={
                  tab === t
                    ? "rounded px-3 py-1.5 font-medium text-[#1c140d] bg-accent-300"
                    : "rounded px-3 py-1.5 text-[#696A61] hover:text-[#8F8978]"
                }
              >
                {TAB_LABELS[t]}
              </button>
            ))}
          </div>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto">
        <Activity mode={tab === 'understand' ? 'visible' : 'hidden'}><UnderstandTab allNotions={allNotions}/></Activity>
        <Activity mode={tab === "today" ? "visible" : "hidden"}>
          <TodayTab initialCards={initialTodayCards} />
        </Activity>
        <Activity mode={tab === "drill" ? "visible" : "hidden"}>
          <DrillTab initialCards={initialCards} />
        </Activity>
        <Activity mode={tab === "connect" ? "visible" : "hidden"}>
          <ConnectTab initialCards={initialLinkCards} />
        </Activity>
        <Activity mode={tab === "explain" ? "visible" : "hidden"}>
          <ExplainTab
            allNotions={allNotions}
            llmConfigured={llmConfigured}
            onPracticePronunciation={practicePronunciation}
          />
        </Activity>
        <Activity mode={tab === "pronounce" ? "visible" : "hidden"}>
          <PronounceTab
            initialCards={initialPronunciationCards}
            pendingCard={pendingPronunciationCard}
            llmConfigured={llmConfigured}
          />
        </Activity>
        <Activity mode={tab === "vocab" ? "visible" : "hidden"}>
          <VocabTab initialCards={initialVocabularyCards} />
        </Activity>
      </div>
    </div>
  );
}

import NotionEditor from "@/components/NotionEditor";
import { useEffect, useState } from "react";
import { colorForDomain, type Document, type Link, type Notion } from "@/lib/types";
import type { ChatTurn } from "@/lib/llm";
import type { MasteryInfo } from "@/lib/mastery";
import ChatPanel from "@/components/ChatPanel";
import ClairReader from '@/components/ClairReader';

export type Selection =
  | { kind: "node"; notion: Notion }
  | { kind: "edge"; link: Link; source: Notion; target: Notion };

const MASTERY_BADGE: Record<MasteryInfo["level"], { label: string; color: string }> = {
  unknown: { label: "Untested", color: "#696A61" },
  weak: { label: "Weak", color: "#ef4444" },
  learning: { label: "Learning", color: "#f97316" },
  developing: { label: "Developing", color: "#eab308" },
  mastered: { label: "Mastered", color: "#22c55e" },
};

interface SidePanelProps {
  courseId:string;
  selection: Selection | null;
  documents: Document[];
  mastery: Record<string, MasteryInfo>;
  llmConfigured: boolean;
  decomposing: boolean;
  onDecompose: (notionId: string) => void;
  goingFurther: boolean;
  onGoFurther: (notionId: string) => void;
  adeptGenerating: boolean;
  onGenerateAdept: (notionId: string) => void;
  onToggleStatus: (notionId: string) => void;
  onEditNotion: (notion:Notion)=>void;
  chatMessages: ChatTurn[];
  chatLoading: boolean;
  onSendChat: (text: string) => void;
  onDelete: (notionId: string) => void;
  similarNotion: Notion | null;
  onMerge: (fromId: string, intoId: string) => void;
  allNotions: Notion[];
}

export default function SidePanel({
  courseId,
  selection,
  documents,
  mastery,
  llmConfigured,
  decomposing,
  onDecompose,
  goingFurther,
  onGoFurther,
  adeptGenerating,
  onGenerateAdept,
  onToggleStatus,
  onEditNotion,
  chatMessages,
  chatLoading,
  onSendChat,
  onDelete,
  similarNotion,
  onMerge,
  allNotions,
}: SidePanelProps) {
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  const [mergePickerOpen, setMergePickerOpen] = useState(false);
  const [mergeQuery, setMergeQuery] = useState("");

  // Delete/Backspace opens the same confirmation the ✕ button does —
  // never deletes outright, a destructive action still needs that click.
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Delete" && e.key !== "Backspace") return;
      if (!selection || selection.kind !== "node") return;
      const target = e.target as HTMLElement | null;
      if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) return;
      e.preventDefault();
      setConfirmingDelete(true);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [selection]);

  if (!selection) {
    return (
      <aside className="flex h-full w-full flex-col items-center justify-center border-l border-[#423e42] bg-[#201f21] p-6 text-center text-sm text-[#696A61]">
        Click a node or a link in the graph to see its details here.
      </aside>
    );
  }

  if (selection.kind === "edge") {
    const { link, source, target } = selection;
    return (
      <aside className="flex h-full w-full flex-col overflow-y-auto border-l border-[#423e42] bg-[#201f21] p-5">
        <h3 className="mb-1 text-xs font-semibold uppercase tracking-wide text-[#696A61]">
          {link.type.replace("-", " ")}
        </h3>
        <div className="mb-4 flex items-center gap-1.5 text-sm font-medium text-[#D4C6A6]">
          <span style={{ color: colorForDomain(source.domain) }}>{source.label}</span>
          <span className="text-[#696A61]">→</span>
          <span style={{ color: colorForDomain(target.domain) }}>{target.label}</span>
        </div>
        <p className="text-sm leading-relaxed text-[#8F8978]">{link.description}</p>
        {link.evidence?.map((e,i)=><blockquote key={i} className="my-3 border-l-2 border-accent-400 pl-3 text-xs"><a className="text-accent-300" target="_blank" rel="noreferrer" href={`/api/documents/${e.documentId}/file#page=${e.page}`}>Slide {e.page}</a><p>{e.quote}</p></blockquote>)}
      </aside>
    );
  }

  const { notion } = selection;
  const color = colorForDomain(notion.domain);
  const masteryInfo = mastery[notion.id];
  const masteryBadge = MASTERY_BADGE[masteryInfo?.level ?? "unknown"];

  return (
    <aside className="flex h-full w-full flex-col overflow-y-auto border-l border-[#423e42] bg-[#201f21] p-5">
      <div className="mb-3 flex items-center gap-2">
        <span
          className="rounded-full px-2 py-0.5 text-xs font-medium text-white"
          style={{ backgroundColor: color, boxShadow: `0 0 10px ${color}66` }}
        >
          {notion.domain}
        </span>
        <span
          className="flex items-center gap-1 rounded-full border border-[#423e42] bg-[#28262a] px-2 py-0.5 text-xs text-[#8F8978]"
          title="Mastery — derived from Drill/Connect/Explain/Interview performance, separate from the SRS review schedule"
        >
          <span className="h-1.5 w-1.5 rounded-full" style={{ backgroundColor: masteryBadge.color }} />
          {masteryBadge.label}
        </span>
        <button
          onClick={() => onToggleStatus(notion.id)}
          className={
            notion.status === "draft"
              ? "rounded border border-dashed border-[#696A61] px-2 py-0.5 text-xs text-[#696A61] hover:border-[#8F8978] hover:text-[#8F8978]"
              : "rounded border border-emerald-500/40 bg-emerald-500/10 px-2 py-0.5 text-xs text-emerald-400 hover:bg-emerald-500/20"
          }
          title="Click to toggle draft/validated"
        >
          {notion.status === "draft" ? "Draft" : "Validated"}
        </button>

        <button
          onClick={() => setConfirmingDelete(true)}
          title="Delete this notion"
          className="ml-auto rounded px-1.5 py-0.5 text-xs text-[#696A61] hover:bg-red-500/10 hover:text-red-400"
        >
          ✕
        </button>
      </div>

      <NotionEditor key={notion.id} courseId={courseId} notion={notion} onSave={onEditNotion}/>
      <p className="mb-3 text-xs text-[#8F8978]">Content: {notion.layer ?? "legacy / unclassified"}</p>
      {!!notion.evidence?.length && <details className="mb-3 text-xs text-[#8F8978]">
        <summary className="cursor-pointer text-accent-300">Sources · {notion.evidence.length} references</summary>
        <div className="mt-3">{notion.evidence.map((e,i)=><blockquote key={i} className="mb-3 border-l-2 border-accent-400 pl-3"><a target="_blank" rel="noreferrer" href={`/api/documents/${e.documentId}/file#page=${e.page}`} className="text-accent-300">Slide {e.page}</a><p>{e.quote || e.visualDescription}</p></blockquote>)}</div>
      </details>}
      {confirmingDelete && (
        <div className="mb-3 rounded-md border border-red-500/30 bg-red-500/10 p-2.5 text-xs text-red-300">
          <p className="mb-2">
            Delete &quot;{notion.label}&quot; and every link touching it? This can&apos;t be undone.
          </p>
          <div className="flex gap-2">
            <button
              onClick={() => onDelete(notion.id)}
              className="rounded border border-red-500/40 bg-red-500/20 px-2 py-1 text-red-200 hover:bg-red-500/30"
            >
              Delete
            </button>
            <button
              onClick={() => setConfirmingDelete(false)}
              className="rounded border border-[#423e42] px-2 py-1 text-[#8F8978] hover:bg-[#322f33]"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {similarNotion && (
        <div className="mb-3 rounded-md border border-amber-500/30 bg-amber-500/10 p-2.5 text-xs text-amber-300">
          <p className="mb-2">
            This looks like it might be a duplicate of <strong>{similarNotion.label}</strong>.
          </p>
          <button
            onClick={() => onMerge(notion.id, similarNotion.id)}
            className="rounded border border-amber-500/40 bg-amber-500/20 px-2 py-1 text-amber-200 hover:bg-amber-500/30"
          >
            Merge into &quot;{similarNotion.label}&quot;
          </button>
        </div>
      )}

      <div className="mb-3">
        {mergePickerOpen ? (
          <div className="rounded-md border border-[#423e42] bg-[#201f21] p-2.5">
            <input
              autoFocus
              value={mergeQuery}
              onChange={(e) => setMergeQuery(e.target.value)}
              placeholder="Search a notion to merge into…"
              className="mb-2 w-full rounded border border-[#423e42] bg-[#28262a] px-2 py-1 text-xs text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
            />
            {mergeQuery.trim().length > 0 && (
              <ul className="max-h-36 space-y-0.5 overflow-y-auto">
                {allNotions
                  .filter(
                    (n) =>
                      n.id !== notion.id &&
                      n.label.toLowerCase().includes(mergeQuery.trim().toLowerCase())
                  )
                  .slice(0, 6)
                  .map((n) => (
                    <li key={n.id}>
                      <button
                        onClick={() => {
                          onMerge(notion.id, n.id);
                          setMergePickerOpen(false);
                          setMergeQuery("");
                        }}
                        className="block w-full truncate rounded px-2 py-1 text-left text-xs text-[#8F8978] hover:bg-[#322f33]"
                        title={`Merge "${notion.label}" into "${n.label}"`}
                      >
                        {n.label}
                      </button>
                    </li>
                  ))}
              </ul>
            )}
            <button
              onClick={() => {
                setMergePickerOpen(false);
                setMergeQuery("");
              }}
              className="mt-1 text-xs text-[#696A61] hover:text-[#8F8978]"
            >
              Cancel
            </button>
          </div>
        ) : (
          <button
            onClick={() => setMergePickerOpen(true)}
            className="text-xs text-[#696A61] hover:text-[#8F8978]"
          >
            Merge with another notion…
          </button>
        )}
      </div>

      <h2 className="mb-2 text-lg font-semibold text-[#D4C6A6]">{notion.label}</h2>

      {notion.grounding === "inferred" && (
        <div className="mb-3 rounded-md border border-amber-500/30 bg-amber-500/10 px-2.5 py-2 text-xs text-amber-300">
          ⚠ The source material here was too sparse to ground this in (e.g. a bare slide bullet) —
          this explanation was filled in from the AI&apos;s general knowledge instead. Worth
          double-checking against the real source.
        </div>
      )}

      <div className="mb-4">
        <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-accent-400">Quick answer</p>
        <p className="text-sm font-medium leading-relaxed text-[#8F8978]">{notion.definition}</p>
      </div>

      {notion.clair ? <div className="mb-5"><ClairReader key={notion.id} lesson={notion.clair}/></div> : notion.explanation ? (
        <div className="mb-5">
          <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-accent-400">Explanation</p>
          <div className="space-y-3">
            {notion.explanation
              .split(/\n\s*\n/)
              .map((p) => p.trim())
              .filter(Boolean)
              .map((paragraph, i) => (
                <p key={i} className="whitespace-pre-line text-sm leading-relaxed text-[#8F8978]">
                  {paragraph}
                </p>
              ))}
          </div>
        </div>
      ) : (
        <p className="mb-5 text-xs italic text-[#696A61]">
          No detailed explanation yet — decompose it or ask about it below to flesh it out.
        </p>
      )}

      {notion.courseContext && (
        <div className="mb-5">
          <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-accent-400">In this course</p>
          <p className="text-sm italic leading-relaxed text-[#8F8978]">{notion.courseContext}</p>
        </div>
      )}


      {notion.workQuestions && notion.workQuestions.length > 0 && (
        <div className="mb-5 space-y-3 rounded-md border border-[#423e42] bg-[#201f21] p-3">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-accent-400">
            On the job, you might get asked
          </p>
          <ul className="space-y-3">
            {notion.workQuestions.map((wq, i) => (
              <li key={i}>
                <p className="text-sm font-medium leading-relaxed text-[#D4C6A6]">{wq.question}</p>
                {wq.answer ? (
                  <p className="mt-0.5 text-sm leading-relaxed text-[#8F8978]">{wq.answer}</p>
                ) : (
                  <p className="mt-0.5 text-xs italic text-[#696A61]">No saved answer yet.</p>
                )}
              </li>
            ))}
          </ul>
        </div>
      )}

      {notion.adept && (
        <div className="mb-5 space-y-3 rounded-md border border-[#423e42] bg-[#201f21] p-3">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-accent-400">ADEPT breakdown</p>
          {(
            [
              ["Analogy", notion.adept.analogy],
              ["Diagram", notion.adept.diagram],
              ["Example", notion.adept.example],
              ["Plain English", notion.adept.plainEnglish],
              ["Technical", notion.adept.technical],
            ] as const
          ).map(([label, text]) => (
            <div key={label}>
              <p className="text-xs font-medium text-[#8F8978]">{label}</p>
              <p className="text-sm leading-relaxed text-[#8F8978]">{text}</p>
            </div>
          ))}
        </div>
      )}

      {notion.goFurther && (
        <div className="mb-5 space-y-3 rounded-md border border-[#423e42] bg-[#201f21] p-3">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-accent-400">Go further</p>
          {(
            [
              ["More examples", notion.goFurther.moreExamples],
              ["What comes next", notion.goFurther.nextStep],
              ["Worth looking into", notion.goFurther.references],
            ] as const
          ).map(([label, text]) => (
            <div key={label}>
              <p className="text-xs font-medium text-[#8F8978]">{label}</p>
              <p className="text-sm leading-relaxed text-[#8F8978]">{text}</p>
            </div>
          ))}
        </div>
      )}

      {notion.sources.length > 0 && (
        <div className="mb-5">
          <h3 className="mb-2 text-xs font-semibold uppercase tracking-wide text-[#696A61]">
            Sources
          </h3>
          <ul className="space-y-1.5">
            {notion.sources.map((source, index) => {
              const doc = documents.find((d) => d.id === source.documentId);
              return (
                <li key={index} className="text-sm text-[#8F8978]">
                        <span className="font-medium text-[#8F8978]">{doc?.title ?? source.documentId}</span><span className="text-[#696A61]"> — p. {source.page}</span>
                </li>
              );
            })}
          </ul>
        </div>
      )}

      <div className="mb-5 space-y-2 border-t border-[#423e42] pt-4">
        <button
          onClick={() => onDecompose(notion.id)}
          disabled={!llmConfigured || decomposing}
          title={llmConfigured ? undefined : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"}
          className="w-full rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33] disabled:cursor-not-allowed disabled:opacity-40"
        >
          {decomposing ? "Breaking down…" : "Break down into sub-notions"}
        </button>
        <button
          onClick={() => onGoFurther(notion.id)}
          disabled={!llmConfigured || goingFurther}
          title={
            llmConfigured
              ? "Adds more examples, the next direction, and references to this notion's own text"
              : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"
          }
          className="w-full rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33] disabled:cursor-not-allowed disabled:opacity-40"
        >
          {goingFurther ? "Looking ahead…" : notion.goFurther ? "Regenerate go further" : "Go further →"}
        </button>
        <button
          onClick={() => onGenerateAdept(notion.id)}
          disabled={!llmConfigured || adeptGenerating}
          title={
            llmConfigured
              ? "Explain via analogy, diagram, example, plain English, and the technical definition"
              : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"
          }
          className="w-full rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33] disabled:cursor-not-allowed disabled:opacity-40"
        >
          {adeptGenerating ? "Breaking it down…" : notion.adept ? "Regenerate ADEPT breakdown" : "Explain with ADEPT"}
        </button>
      </div>

      <ChatPanel
        messages={chatMessages}
        loading={chatLoading}
        disabled={!llmConfigured}
        disabledReason={llmConfigured ? undefined : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"}
        onSend={onSendChat}
      />
    </aside>
  );
}

"use client";

import { useMemo, useState } from "react";
import type { Notion } from "@/lib/types";

interface SearchBarProps {
  notions: Notion[];
  query: string;
  onQueryChange: (query: string) => void;
  onPickNotion: (id: string) => void;
}

export default function SearchBar({
  notions,
  query,
  onQueryChange,
  onPickNotion,
}: SearchBarProps) {
  const [focused, setFocused] = useState(false);

  const matches = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    return notions.filter((n) => n.label.toLowerCase().includes(q)).slice(0, 8);
  }, [notions, query]);

  return (
    <div className="relative w-44">
      <input
        value={query}
        onChange={(e) => onQueryChange(e.target.value)}
        onFocus={() => setFocused(true)}
        onBlur={() => setTimeout(() => setFocused(false), 100)}
        placeholder="Search a notion..."
        className="w-full rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none focus:ring-1 focus:ring-accent-400/30"
      />
      {focused && matches.length > 0 && (
        <ul
          style={{ zIndex: 9999 }}
          className="absolute mt-1 w-full overflow-hidden rounded-md border border-[#423e42] bg-[#28262a] shadow-xl"
        >
          {matches.map((notion) => (
            <li key={notion.id}>
              <button
                onClick={() => {
                  onPickNotion(notion.id);
                  onQueryChange("");
                }}
                className="block w-full px-3 py-1.5 text-left text-sm text-[#8F8978] hover:bg-[#322f33]"
              >
                {notion.label}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

"use client";
import { useContext, useEffect, useState } from "react";
import { StudySessionContext } from "@/lib/useStudySession";
export default function ReviewIntervals({type,id}:{type:string;id:string}) {
  const {courseId}=useContext(StudySessionContext), [labels,setLabels]=useState<string[]>([]);
  useEffect(()=>{const controller=new AbortController();fetch(`/api/review/${type}/${id}/intervals`,{signal:controller.signal,headers:{"X-Course-Id":courseId}}).then(r=>r.ok?r.json():null).then(data=>{if(data)setLabels(data.labels);}).catch(()=>{});return()=>controller.abort();},[type,id,courseId]);
