"use client";
import { useEffect, useState } from "react";
import type { PageAnalysis } from "@/lib/qualityDb";
import { useCourseFetch } from "@/lib/useCourseFetch";
interface QualityData {runs:Array<{id:string;payload:string}>;summary:Record<string,number>;settings:{newPerDay:number;sessionLimit:number};documents:Array<{id:string;title:string;pageCount?:number;pages:PageAnalysis[]}>;}
export default function QualityPanel({courseId}:{courseId:string}) {
  const fetch=useCourseFetch(courseId);
  const [data,setData]=useState<QualityData|null>(null),[error,setError]=useState(""),[busy,setBusy]=useState(false);
  useEffect(()=>{const c=new AbortController();fetch("/api/quality",{signal:c.signal}).then(r=>r.json()).then(setData).catch(()=>{});return()=>c.abort();},[fetch]);
  const retry=async(id:string,pages:number[])=>{
    setBusy(true);setError("");
    try {const r=await fetch(`/api/documents/${id}/quality`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({pages})});const body=await r.json();if(!r.ok)throw new Error(body.error);setData(previous=>previous?{...previous,documents:previous.documents.map(d=>d.id===id?{...d,pages:d.pages.filter(p=>!pages.includes(p.page))}:d)}:previous);}
    catch(e){setError(e instanceof Error?e.message:"Retry failed");}finally{setBusy(false);}
  };
  const saveSettings=async()=>{if(!data)return;setBusy(true);try{const res=await fetch("/api/quality",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify(data.settings)});const body=await res.json();setError(res.ok?"Review settings saved":body.error);}catch{setError("Could not save settings");}finally{setBusy(false);}};
  const restorePdf=async(id:string,file:File)=>{setBusy(true);setError("");try{const form=new FormData();form.set("file",file);const response=await fetch(`/api/documents/${id}/file`,{method:"PUT",body:form});const body=await response.json();setError(response.ok?"Original PDF restored. Reprocess the affected pages.":body.error);}catch{setError("Could not restore PDF");}finally{setBusy(false);}};
  if(!data)return null;
  return <details className="mb-6 rounded-lg border border-[#423e42] bg-[#201f21] p-4"><summary className="cursor-pointer">Content quality · {data.summary.draft} drafts · {data.summary.legacy} legacy cards to verify</summary>
    <div className="mt-4 space-y-4 text-sm"><p>{data.summary.unsourcedConcepts} concepts without sources. Legacy cards are preserved; their content has not passed the new audit.</p>
      <div className="flex flex-wrap items-center gap-3"><label>New cards/day <input aria-label="New cards per day" className="w-16 rounded bg-[#28262a] p-1" type="number" min={0} max={200} value={data.settings.newPerDay} onChange={e=>setData({...data,settings:{...data.settings,newPerDay:Number(e.target.value)}})}/></label><label>Session limit <input aria-label="Session limit" className="w-16 rounded bg-[#28262a] p-1" type="number" min={1} max={500} value={data.settings.sessionLimit} onChange={e=>setData({...data,settings:{...data.settings,sessionLimit:Number(e.target.value)}})}/></label><button disabled={busy} onClick={saveSettings} className="rounded border border-[#423e42] p-2">Save settings</button></div>
      {data.documents.map(doc=><details key={doc.id} className="rounded border border-[#423e42] p-3"><summary>{doc.title} · {doc.pages.filter(p=>p.status==="complete").length} covered · {doc.pages.filter(p=>p.status==="skipped").length} excluded · {doc.pages.filter(p=>p.status==="retry").length} to retry</summary>
        <p className="my-2 text-xs text-[#8F8978]">Pages without an audit include older generations. Reset selected pages, then generate from Documents. Existing cards and edits are kept.</p>
        <label className="mb-3 block text-xs text-[#8F8978]">Restore the original PDF from an older backup <input className="mt-1 block" type="file" accept="application/pdf" disabled={busy} onChange={e=>{const file=e.target.files?.[0];if(file)void restorePdf(doc.id,file);}}/></label>
        <div className="max-h-64 space-y-2 overflow-y-auto">{Array.from({length:doc.pageCount ?? 0},(_,i)=>i+1).map(page=>{const p=doc.pages.find(p=>p.page===page);return <div key={page} className="flex items-start justify-between gap-3 border-t border-[#423e42] pt-2"><div><a target="_blank" rel="noreferrer" className="text-accent-300" href={`/api/documents/${doc.id}/file#page=${page}`}>Slide {page}</a> · {p?.status ?? "not audited"} · {p?.kind ?? "unknown"}<p className="text-xs text-[#8F8978]">{p?.reason}{p && ` · ${p.concepts} concepts · ${p.cards} cards`}</p>{p?.warnings.map((w,i)=><p key={i} className="text-xs text-amber-300">{w}</p>)}</div><button disabled={busy} className="shrink-0 rounded border border-[#423e42] px-2 py-1 text-xs" onClick={()=>retry(doc.id,[page])}>Reprocess</button></div>;})}</div>
      </details>)}
      {data.runs.length>0 && <details><summary>Recent generation runs</summary>{data.runs.slice(-5).reverse().map(run=>{const metrics=JSON.parse(run.payload);return <p className="mt-2 text-xs text-[#8F8978]" key={run.id}>{metrics.model} · {metrics.version} · {metrics.status} · {metrics.calls} calls · {metrics.pages} pages · {metrics.cards} cards · {metrics.rejected} rejected · {metrics.inputTokens ?? 0} input tokens · {metrics.outputTokens ?? 0} output tokens</p>;})}</details>}
      {error && <p role="status">{error}</p>}
    </div>
  </details>;
}

"use client";
import { useReview } from "@/lib/useReview";
import ReviewIntervals from "@/components/ReviewIntervals";

import { useEffect, useState } from "react";
import { useStudyQueue, useStudyState } from "@/lib/useStudySession";
import type { PronunciationCard, PronunciationWord } from "@/lib/db";
import type { Grade } from "@/lib/srs";
import { PRONUNCIATION_RULES } from "@/lib/pronunciation";
import { notifyXpUpdated } from "@/lib/xpEvent";
import { useCardShortcuts } from "@/lib/useCardShortcuts";

interface DuePronunciationCard {
  card: PronunciationCard;
  isNew: boolean;
}

interface PronounceTabProps {
  initialCards: DuePronunciationCard[];
  pendingCard: PronunciationCard | null;
  llmConfigured: boolean;
}

const GRADE_OPTIONS: Array<{ grade: Grade; label: string; hint: string; className: string }> = [
  { grade: "again", label: "Again", hint: "couldn't say it right", className: "bg-red-500/20 border-red-500/40 text-red-200 hover:bg-red-500/30" },
  { grade: "hard", label: "Hard", hint: "struggled", className: "bg-amber-500/20 border-amber-500/40 text-amber-200 hover:bg-amber-500/30" },
  { grade: "good", label: "Good", hint: "got it", className: "bg-emerald-500/20 border-emerald-500/40 text-emerald-200 hover:bg-emerald-500/30" },
  { grade: "easy", label: "Easy", hint: "trivial", className: "bg-accent-500/20 border-accent-500/40 text-accent-200 hover:bg-accent-500/30" },
];

export function stressClassName(stress: "primary" | "secondary" | "none") {
  if (stress === "primary") return "font-semibold text-accent-200 underline underline-offset-4";
  if (stress === "secondary") return "text-[#D4C6A6]";
  return "text-[#696A61]";
}

// Groups adjacent words that blend together in connected speech (liaison)
// so the UI can draw one visual link across the pair instead of treating
// them as two independent words.
export function groupLinkedWords(words: PronunciationWord[]): Array<PronunciationWord[]> {
  const groups: Array<PronunciationWord[]> = [];
  let i = 0;
  while (i < words.length) {
    const w = words[i];
    if (w.linksToNext && w.blendWithNext && words[i + 1]) {
      groups.push([w, words[i + 1]]);
      i += 2;
    } else {
      groups.push([w]);
      i += 1;
    }
  }
  return groups;
}

export function WordCell({ word }: { word: PronunciationWord }) {
  return (
    <span className="inline-block align-top">
      <span className={stressClassName(word.sentenceStress)}>{word.word}</span>
      <br />
      <span className="text-xs text-[#696A61]">{word.syllables}</span>
      <br />
      <span className="text-[11px] text-[#696A61]">{word.ipa}</span>
      {word.note && <span className="block max-w-[8rem] text-[10px] text-amber-400/80">{word.note}</span>}
    </span>
  );
}

// Renders two liaising words joined by a curved "wave" (the visual analogue
// of the IPA tie bar ‿), with the blended colloquial form captioned below —
// e.g. "let" + "me" drawn with an arc under them and "≈ lemme" underneath.
export function LinkedPair({ words }: { words: [PronunciationWord, PronunciationWord] }) {
  const [a, b] = words;
  return (
    <span className="inline-flex flex-col items-center">
      <span className="flex gap-3">
        <WordCell word={a} />
        <WordCell word={b} />
      </span>
      <svg viewBox="0 0 100 16" preserveAspectRatio="none" className="mt-0.5 h-3 w-16 text-accent-400">
        <path d="M4,2 Q50,16 96,2" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" />
      </svg>
      <span className="text-[10px] italic text-accent-300">≈ &ldquo;{a.blendWithNext}&rdquo;</span>
    </span>
  );
}

function RulesPanel() {
  const [open, setOpen] = useState(false);
  return (
    <div className="mb-5 shrink-0">
      <button onClick={() => setOpen((v) => !v)} className="text-xs text-[#696A61] hover:text-[#8F8978]">
        {open ? "▾" : "▸"} Pronunciation rules
      </button>
      {open && (
        <div className="mt-2 space-y-3 rounded-md border border-[#423e42] bg-[#201f21] p-3">
          {PRONUNCIATION_RULES.map((rule) => (
            <div key={rule.title}>
              <p className="text-sm font-medium text-[#D4C6A6]">{rule.title}</p>
              <p className="mt-0.5 text-xs leading-relaxed text-[#696A61]">{rule.body}</p>
              <ul className="mt-1 space-y-0.5">
                {rule.examples.map((ex) => (
                  <li key={ex} className="text-xs text-[#8F8978]">
                    {ex}
                  </li>
                ))}
              </ul>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const restorePendingId = (value: unknown) => typeof value === "string" || value === null ? value : null;

export default function PronounceTab({ initialCards, pendingCard, llmConfigured }: PronounceTabProps) {
  const { cards, setCards, index, setIndex, revealed, setRevealed, sessionDone, setSessionDone, reviewedCount, setReviewedCount } = useStudyQueue("pronounce", initialCards);
  const saveReview=useReview("pronounce");
  const [grading, setGrading] = useState(false);
  const [gradeError, setGradeError] = useState<string | null>(null);
  const [freeText, setFreeText] = useStudyState("pronounce-text", "");
  const [generating, setGenerating] = useState(false);
  const [generateError, setGenerateError] = useState<string | null>(null);
  const [lastPendingId, setLastPendingId] = useStudyState<string | null>("pronounce-last-pending", null, restorePendingId);

  // Consume the handoff once, without interrupting the existing queue.
  useEffect(() => {
    if (!pendingCard || pendingCard.id === lastPendingId) return;
    setLastPendingId(pendingCard.id);
    setCards((prev) => [{ card: pendingCard, isNew: true }, ...prev.slice(index).filter((entry) => entry.card.id !== pendingCard.id)]);
    setIndex(0);
    setRevealed(false);
    setSessionDone(false);
  }, [pendingCard, lastPendingId, index, setLastPendingId, setCards, setIndex, setRevealed, setSessionDone]);

  const current = cards[index];

  const grade = async (g: Grade) => {
    if (!current || grading) return;
    setGrading(true);
    setGradeError(null);
    try {
      const res = await saveReview("pronunciation", current.card.id, g);
      if (!res.ok) throw new Error("Your review could not be saved. Please try again.");
      notifyXpUpdated();
      setReviewedCount((n) => n + 1);
      if (index + 1 >= cards.length) {
        setSessionDone(true);
      } else {
        setIndex((i) => i + 1);
        setRevealed(false);
      }
    } catch (error) {
      setGradeError(error instanceof Error ? error.message : "Your review could not be saved. Please try again.");
    } finally {
      setGrading(false);
    }
  };

  const restart = async () => {
    const res = await fetch("/api/pronunciation/queue");
    if (res.ok) {
      const data = await res.json();
      setCards(data.cards);
      setIndex(0);
      setRevealed(false);
      setReviewedCount(0);
      setSessionDone(data.cards.length === 0);
    }
  };

  useCardShortcuts({
    revealed,
    onReveal: () => setRevealed(true),
    onGrade: grade,
    disabled: grading || sessionDone || !current,
  });

  const generateFromText = async () => {
    if (freeText.trim().length < 3 || generating) return;
    setGenerating(true);
    setGenerateError(null);
    try {
      const res = await fetch("/api/pronunciation/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ text: freeText.trim() }),
      });
      const data = await res.json();
      if (!res.ok) {
        setGenerateError(data.error ?? "Could not generate a card.");
        return;
      }
      setCards((prev) => [{ card: data.card, isNew: true }, ...prev]);
      setIndex(0);
      setRevealed(false);
      setSessionDone(false);
      setFreeText("");
    } finally {
      setGenerating(false);
    }
  };

  const generatorBlock = (
    <div className="mb-5 shrink-0 rounded-md border border-[#423e42] bg-[#201f21] p-3">
      <p className="mb-2 text-xs text-[#696A61]">Or paste any English text to practice its pronunciation:</p>
      <textarea
        value={freeText}
        onChange={(e) => setFreeText(e.target.value)}
        rows={2}
        placeholder="A sentence or short paragraph…"
        className="w-full resize-none rounded-md border border-[#423e42] bg-[#28262a] p-2 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
      />
      <button
        onClick={generateFromText}
        disabled={!llmConfigured || generating || freeText.trim().length < 3}
        title={llmConfigured ? undefined : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"}
        className="mt-2 rounded-md border border-[#423e42] bg-[#322f33] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#1d2829] disabled:cursor-not-allowed disabled:opacity-40"
      >
        {generating ? "Generating…" : "Generate pronunciation card"}
      </button>
      {generateError && <p className="mt-2 text-xs text-red-400">{generateError}</p>}
    </div>
  );

  if (sessionDone) {
    return (
      <div className="mx-auto flex h-full max-w-2xl flex-col px-6 py-10">
        <RulesPanel />
        {generatorBlock}
        <div className="flex flex-1 flex-col items-center justify-center gap-4 text-center">
          <p className="text-lg text-[#D4C6A6]">
            {reviewedCount > 0
              ? `Session done — ${reviewedCount} card${reviewedCount > 1 ? "s" : ""} practiced.`
              : "No pronunciation cards due. Generate one from an Explain attempt, or paste text above."}
          </p>
          <button
            onClick={restart}
            className="rounded-md border border-[#423e42] bg-[#28262a] px-4 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33]"
          >
            Check again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto flex h-full max-w-2xl flex-col px-6 py-8 overflow-y-auto">
      {gradeError && <p role="alert" className="mb-3 text-sm text-red-400">{gradeError}</p>}
      {revealed && <ReviewIntervals type="pronunciation" id={current.card.id}/>}
      <RulesPanel />
      {generatorBlock}

      <div className="mb-3 flex shrink-0 items-center justify-between text-xs text-[#696A61]">
        <span>
          Card {index + 1} / {cards.length}
        </span>
        {current.isNew && <span className="text-accent-400">new</span>}
      </div>

      <div className="mb-6 rounded-lg border border-[#423e42] bg-[#201f21] p-6">
        {!revealed ? (
          <p className="text-base leading-relaxed text-[#8F8978]">{current.card.text}</p>
        ) : (
          <>
            {current.card.fullIpa && (
              <p className="mb-4 border-b border-[#423e42] pb-3 text-center text-sm text-accent-200">
                {current.card.fullIpa}
              </p>
            )}
            <p className="flex flex-wrap items-start gap-x-3 gap-y-4 text-base leading-relaxed">
              {groupLinkedWords(current.card.words).map((group, i) =>
                group.length === 2 ? (
                  <LinkedPair key={i} words={group as [PronunciationWord, PronunciationWord]} />
                ) : (
                  <WordCell key={i} word={group[0]} />
                )
              )}
            </p>
          </>
        )}
      </div>

      {!revealed ? (
        <button
          onClick={() => setRevealed(true)}
          className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829]"
        >
          Reveal pronunciation <span className="text-[#696A61]">(space)</span>
        </button>
      ) : (
        <div className="grid grid-cols-4 gap-2">
          {GRADE_OPTIONS.map((opt, idx) => (
            <button
              key={opt.grade}
              onClick={() => grade(opt.grade)}
              disabled={grading}
              title={opt.hint}
              className={`rounded-md border px-3 py-2.5 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50 ${opt.className}`}
            >
              {opt.label} <span className="opacity-60">{idx + 1}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import { colorForDomain, type Domain, type NotionStatus } from "@/lib/types";
import type { MasteryLevel } from "@/lib/mastery";

export interface NotionLabelProps {
  label: string;
  domain: Domain;
  status: NotionStatus;
  dimmed: boolean;
  active: boolean;
  depth: number;
  masteryLevel: MasteryLevel;
}

// ⚪🔴🟠🟡🟢 — separate from the domain-color dot inside the node (which
// identifies the CATEGORY a notion belongs to); this one is mastery: how
// well it's actually known, derived from performance across Drill/Connect/
// Explain/Interview (lib/mastery.ts), nothing to do with SRS due dates.
export const MASTERY_COLORS: Record<MasteryLevel, string> = {
  unknown: "#696A61",
  weak: "#ef4444",
  learning: "#f97316",
  developing: "#eab308",
  mastered: "#22c55e",
};

// Visual weight by hierarchy depth — depth 0 (foundational/root notions)
// reads biggest and boldest, deeper sub-notions progressively shrink and
// lighten. Without this every notion looked equally important regardless of
// where it actually sits in the course's structure.
const DEPTH_TIERS = [
  { box: "min-w-[190px] max-w-[240px] px-5 py-3", text: "text-sm font-semibold text-[#D4C6A6]", dot: "h-2.5 w-2.5" },
  { box: "min-w-[170px] max-w-[220px] px-4 py-2.5", text: "text-[13px] font-medium text-[#D4C6A6]", dot: "h-2 w-2" },
  { box: "min-w-[150px] max-w-[200px] px-3 py-2", text: "text-xs font-normal text-[#8F8978]", dot: "h-1.5 w-1.5" },
  { box: "min-w-[130px] max-w-[180px] px-2.5 py-1.5", text: "text-[11px] font-normal text-[#8F8978]", dot: "h-1.5 w-1.5" },
];

// Rendered as a node's `data.label` (a plain React node), not as a React Flow
// custom node type — registering any `nodeTypes` map currently makes all
// edges disappear in @xyflow/react 12.x (xyflow/xyflow#6042).
export default function NotionLabel({ label, domain, status, dimmed, active, depth, masteryLevel }: NotionLabelProps) {
  const color = colorForDomain(domain);
  const tier = DEPTH_TIERS[Math.min(depth, DEPTH_TIERS.length - 1)];
  const masteryColor = MASTERY_COLORS[masteryLevel];

  return (
    <div
      style={{
        opacity: dimmed ? 0.2 : 1,
        borderColor: active ? color : "rgba(255,255,255,0.08)",
        boxShadow: active
          ? `0 0 0 1px ${color}, 0 0 18px -2px ${color}99`
          : `0 1px 2px rgba(0,0,0,0.4)`,
      }}
      className={`${tier.box} relative rounded-full border bg-[#28262a] transition-all duration-200 hover:border-[color:var(--dot)]`}
    >
      <span
        title={`Mastery: ${masteryLevel}`}
        className="absolute -right-1 -top-1 h-3 w-3 rounded-full border-2 border-[#1a1a1b]"
        style={{ backgroundColor: masteryColor, boxShadow: `0 0 6px 0 ${masteryColor}99` }}
      />
      <div className="flex items-center gap-2">
        <span
          className={`${tier.dot} shrink-0 rounded-full`}
          style={{ backgroundColor: color, boxShadow: `0 0 8px 1px ${color}aa` }}
        />
        <span className={`${tier.text} truncate leading-tight`}>{label}</span>
        {status === "draft" && (
          <span className="ml-auto shrink-0 rounded border border-dashed border-[#696A61] px-1 text-[9px] uppercase tracking-wide text-[#696A61]">
            draft
          </span>
        )}
      </div>
    </div>
  );
}

