"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { InterviewSession } from "@/lib/db";
import { useCourseFetch } from '@/lib/useCourseFetch';

interface InterviewClientProps {
  courseId: string;
  initialSessions: InterviewSession[];
  llmConfigured: boolean;
}

type Mode = "setup" | "live" | "review";

function formatClock(totalSeconds: number): string {
  const s = Math.max(0, Math.round(totalSeconds));
  const m = Math.floor(s / 60);
  const sec = s % 60;
  return `${m}:${sec.toString().padStart(2, "0")}`;
}

function remainingSeconds(session: InterviewSession): number {
  const elapsed = (Date.now() - new Date(session.startedAt).getTime()) / 1000;
  return session.durationMinutes * 60 - elapsed;
}

export default function InterviewClient({ initialSessions, llmConfigured, courseId }: InterviewClientProps) {
  const fetch = useCourseFetch(courseId);
  const [mode, setMode] = useState<Mode>("setup");
  const [sessions, setSessions] = useState(initialSessions);
  const [active, setActive] = useState<InterviewSession | null>(null);

  const [jobTitle, setJobTitle] = useState("");
  const [interviewKind, setInterviewKind] = useState<'job' | 'course'>('job');
  const [unaided, setUnaided] = useState(false);
  const [answerError, setAnswerError] = useState<string | null>(null);
  const [jobDescription, setJobDescription] = useState("");
  const [cvFile, setCvFile] = useState<File | null>(null);
  const [coverLetter, setCoverLetter] = useState("");
  const [starting, setStarting] = useState(false);
  const [startError, setStartError] = useState<string | null>(null);

  const [questionIndex, setQuestionIndex] = useState(0);
  const [answer, setAnswer] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [tick, setTick] = useState(0);
  const completingRef = useRef(false);

  const refreshHistory = async () => {
    const res = await fetch("/api/interview");
    if (res.ok) {
      const data = await res.json();
      setSessions(data.sessions);
    }
  };

  const finishInterview = async (sessionId: string) => {
    if (completingRef.current) return;
    completingRef.current = true;
    const res = await fetch(`/api/interview/${sessionId}/complete`, { method: "POST" });
    if (res.ok) {
      const data = await res.json();
      setActive(data.session);
      setMode("review");
      refreshHistory();
    }
    completingRef.current = false;
  };

  const remaining = active ? remainingSeconds(active) : 0;
  void tick; // forces a re-render every second so `remaining` is recomputed live

  // Re-render every second while a session is live so the countdown stays
  // current, derived fresh from the real clock each tick (not stored state)
  // so it's correct even after a reload mid-session. The time-up check lives
  // inside the same timer callback rather than a separate effect body.
  useEffect(() => {
    if (mode !== "live" || !active) return;
    const interval = setInterval(() => {
      setTick((t) => t + 1);
      if (remainingSeconds(active) <= 0) finishInterview(active.id);
    }, 1000);
    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mode, active?.id]);

  const startInterview = async () => {
    if (interviewKind === 'job' && jobTitle.trim().length < 2 || starting) return;
    setStarting(true);
    setStartError(null);
    try {
      const form = new FormData();
      form.set('mode', interviewKind);
      form.set("jobTitle", jobTitle.trim());
      if (jobDescription.trim()) form.set("jobDescription", jobDescription.trim());
      if (coverLetter.trim()) form.set("coverLetter", coverLetter.trim());
      if (cvFile) form.set("cv", cvFile);
      form.set("durationMinutes", "20");

      const res = await fetch("/api/interview/start", { method: "POST", body: form });
      const data = await res.json();
      if (!res.ok) {
        setStartError(data.error ?? "Could not start the interview.");
        return;
      }
      const session: InterviewSession = data.session;
      const firstUnanswered = session.exchanges.findIndex((e) => !e.answer);
      setActive(session);
      setQuestionIndex(firstUnanswered === -1 ? 0 : firstUnanswered);
      setAnswer("");
      setUnaided(false);
      setAnswerError(null);
      setMode("live");
    } catch {
      setStartError("Network error while starting the interview.");
    } finally {
      setStarting(false);
    }
  };

  const submitAnswer = async () => {
    if (!active || answer.trim().length < 3 || submitting) return;
    setSubmitting(true);
    setAnswerError(null);
    try {
      const res = await fetch(`/api/interview/${active.id}/answer`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ questionIndex, answerText: answer.trim(), unaided }),
      });
      const data = await res.json();
      if (res.ok) {
        setActive({ ...active, exchanges: data.exchanges });
        setAnswer("");
      } else setAnswerError(data.error ?? 'Your answer could not be saved. Please try again.');
    } catch {setAnswerError('Your answer could not be saved. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const nextQuestion = () => {
    setUnaided(false);
    setAnswerError(null);
    if (!active) return;
    if (questionIndex + 1 >= active.exchanges.length) {
      finishInterview(active.id);
    } else {
      setQuestionIndex((i) => i + 1);
      setAnswer("");
    }
  };

  const resumeOrReview = (session: InterviewSession) => {
    if (session.status === "completed") {
      setActive(session);
      setMode("review");
      return;
    }
    const r = remainingSeconds(session);
    if (r <= 0) {
      finishInterview(session.id);
      return;
    }
    const firstUnanswered = session.exchanges.findIndex((e) => !e.answer);
    setActive(session);
    setQuestionIndex(firstUnanswered === -1 ? session.exchanges.length - 1 : firstUnanswered);
    setAnswer("");
    setMode("live");
  };

  const backToSetup = () => {
    setActive(null);
    setJobTitle("");
    setJobDescription("");
    setCvFile(null);
    setMode("setup");
  };

  const currentExchange = active?.exchanges[questionIndex];
  const answeredSoFar = useMemo(() => active?.exchanges.filter((e) => e.answer).length ?? 0, [active]);

  if (mode === "live" && active && currentExchange) {
    const urgent = remaining < 120;
    return (
      <div className="mx-auto flex max-w-2xl flex-col gap-6 px-6 py-8">
        <div className="flex items-center justify-between text-sm">
          <span className="text-[#8F8978]">
            Question {questionIndex + 1} / {active.exchanges.length} — {active.jobTitle}
          </span>
          <span className={urgent ? "font-semibold text-red-400" : "font-semibold text-accent-300"}>
            {formatClock(remaining)}
          </span>
        </div>

        <div className="rounded-lg border border-[#423e42] bg-[#201f21] p-6">
          <p className="text-base leading-relaxed text-[#D4C6A6]">{currentExchange.question}</p>
        </div>

        {currentExchange.feedback ? (
          <>
            <div className="rounded-md border border-emerald-500/30 bg-emerald-500/10 p-3">
              <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-400">Feedback</p>
              <p className="text-sm leading-relaxed text-[#8F8978]">{currentExchange.feedback}</p>
            </div>
            {currentExchange.correctedAnswer && (
              <div className="space-y-2 rounded-md border border-[#423e42] bg-[#201f21] p-3">
                <p className="text-[10px] font-semibold uppercase tracking-wide text-[#696A61]">
                  Say it better next time
                </p>
                <div>
                  <p className="text-xs font-medium text-[#696A61]">You said</p>
                  <p className="text-sm leading-relaxed text-[#8F8978]">{currentExchange.answer}</p>
                </div>
                <div>
                  <p className="text-xs font-medium text-accent-400">Next time, say</p>
                  <p className="text-sm leading-relaxed text-[#D4C6A6]">{currentExchange.correctedAnswer}</p>
                </div>
              </div>
            )}
            <button
              onClick={nextQuestion}
              className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829]"
            >
              {questionIndex + 1 >= active.exchanges.length ? "Finish interview" : "Next question →"}
            </button>
          </>
        ) : (
          <>
            <textarea
              value={answer}
              onChange={(e) => setAnswer(e.target.value)}
              rows={5}
              placeholder="Type your answer as you would say it out loud…"
              className="w-full resize-none rounded-md border border-[#423e42] bg-[#201f21] p-3 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
            />
            {currentExchange?.learningDimension === 'reconstruction' && <label className="text-xs text-[#8F8978]"><input type="checkbox" checked={unaided} onChange={e => setUnaided(e.target.checked)} className="mr-2"/>I answered without consulting notes or hints</label>}
            {answerError && <p role="alert" className="text-xs text-red-400">{answerError}</p>}
            <div className="flex gap-2">
              <button
                onClick={submitAnswer}
                disabled={submitting || answer.trim().length < 3}
                className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829] disabled:cursor-not-allowed disabled:opacity-40"
              >
                {submitting ? "Grading…" : "Submit answer"}
              </button>
              <button
                onClick={() => finishInterview(active.id)}
                className="rounded-md border border-[#423e42] bg-[#201f21] px-4 py-2.5 text-sm text-[#696A61] hover:bg-[#322f33]"
              >
                End interview now
              </button>
            </div>
          </>
        )}
      </div>
    );
  }

  if (mode === "review" && active) {
    return (
      <div className="mx-auto max-w-2xl px-6 py-8">
        <button onClick={backToSetup} className="mb-4 text-xs text-[#696A61] hover:text-[#8F8978]">
          ← Start a new interview
        </button>
        <h2 className="mb-1 text-lg font-semibold text-[#D4C6A6]">{active.jobTitle}</h2>
        <p className="mb-5 text-xs text-[#696A61]">
          {new Date(active.startedAt).toLocaleString()} · {answeredSoFar} of {active.exchanges.length} questions
          answered
        </p>

        {active.summary && (
          <div className="mb-6 rounded-md border border-accent-500/30 bg-accent-500/10 p-4">
            <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-accent-400">
              Overall assessment
            </p>
            <p className="text-sm leading-relaxed text-[#D4C6A6]">{active.summary}</p>
          </div>
        )}

        <div className="space-y-4">
          {active.exchanges.map((e, i) => (
            <div key={i} className="rounded-md border border-[#423e42] bg-[#201f21] p-3">
              <p className="mb-1.5 text-sm font-medium text-[#D4C6A6]">
                Q{i + 1}. {e.question}
              </p>
              {e.answer ? (
                <>
                  <p className="mb-1.5 text-sm text-[#8F8978]">{e.answer}</p>
                  <p className="text-xs text-emerald-300">{e.feedback}</p>
                  {e.correctedAnswer && (
                    <p className="mt-1.5 text-xs text-accent-400">
                      <span className="font-medium">Next time: </span>
                      {e.correctedAnswer}
                    </p>
                  )}
                </>
              ) : (
                <p className="text-xs text-[#696A61]">Not answered</p>
              )}
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-2xl px-6 py-8">
      <div className="mb-8 rounded-lg border border-[#423e42] bg-[#201f21] p-5">
        <h2 className="mb-1 text-base font-semibold text-[#D4C6A6]">Start a mock interview</h2>
        <p className="mb-4 text-xs text-[#696A61]">
          {interviewKind === 'course' ? 'Explain mechanisms, connect ideas and solve source-based situations. Your weakest skills guide the questions.' : '20 minutes, in English, tailored to the role and your CV — with feedback after each answer.'}
        </p>

        <label className="mb-1 block text-xs text-[#696A61]" htmlFor="interview-kind">Practice</label>
        <select id="interview-kind" value={interviewKind} onChange={e => setInterviewKind(e.target.value as 'job' | 'course')} className="mb-3 w-full rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6]"><option value="job">Job interview</option><option value="course">Course understanding · C.L.A.I.R.</option></select>
        <div hidden={interviewKind === 'course'}>

        <label className="mb-1 block text-xs text-[#696A61]">Job title</label>
        <input
          value={jobTitle}
          onChange={(e) => setJobTitle(e.target.value)}
          placeholder="e.g. Senior Backend Engineer"
          className="mb-3 w-full rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
        />

        <label className="mb-1 block text-xs text-[#696A61]">Job description (optional)</label>
        <textarea
          value={jobDescription}
          onChange={(e) => setJobDescription(e.target.value)}
          rows={3}
          placeholder="Paste the job posting, or leave blank"
          className="mb-3 w-full resize-none rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
        />

        <label className="mb-1 block text-xs text-[#696A61]">Your CV (PDF, optional)</label>
        <input
          type="file"
          accept="application/pdf"
          onChange={(e) => setCvFile(e.target.files?.[0] ?? null)}
          className="mb-4 block w-full text-xs text-[#8F8978] file:mr-3 file:rounded file:border-0 file:bg-white/[0.08] file:px-3 file:py-1.5 file:text-xs file:text-[#D4C6A6] hover:file:bg-white/[0.14]"
        />

        <label className="mb-1 block text-xs text-[#696A61]">Cover letter (optional)</label>
        <textarea
          value={coverLetter}
          onChange={(e) => setCoverLetter(e.target.value)}
          rows={4}
          placeholder="Paste the same cover letter you sent to the recruiter, so questions reflect what they already know about you"
          className="mb-4 w-full resize-none rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
        />

        </div>
        <button
          onClick={startInterview}
          disabled={!llmConfigured || starting || interviewKind === 'job' && jobTitle.trim().length < 2}
          title={llmConfigured ? undefined : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"}
          className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829] disabled:cursor-not-allowed disabled:opacity-40"
        >
          {starting ? "Preparing questions…" : "Start interview"}
        </button>
        {startError && <p className="mt-2 text-xs text-red-400">{startError}</p>}
      </div>

      <h3 className="mb-3 text-sm font-semibold text-[#8F8978]">Past sessions</h3>
      {sessions.length === 0 ? (
        <p className="text-sm text-[#696A61]">No interviews yet.</p>
      ) : (
        <div className="divide-y divide-white/[0.06] rounded-lg border border-[#423e42] bg-[#201f21]">
          {sessions.map((s) => (
            <button
              key={s.id}
              onClick={() => resumeOrReview(s)}
              className="flex w-full items-center justify-between px-4 py-3 text-left hover:bg-white/[0.03]"
            >
              <span>
                <span className="block text-sm text-[#D4C6A6]">{s.jobTitle}</span>
                <span className="block text-xs text-[#696A61]">{new Date(s.startedAt).toLocaleString()}</span>
              </span>
              <span
                className={
                  s.status === "completed"
                    ? "rounded px-2 py-0.5 text-[10px] font-medium bg-emerald-500/15 text-emerald-300"
                    : "rounded px-2 py-0.5 text-[10px] font-medium bg-amber-500/15 text-amber-300"
                }
              >
                {s.status === "completed" ? "completed" : "in progress"}
              </span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import NextLink from "next/link";
import type { ReactFlowInstance } from "@xyflow/react";

import Graph from "@/components/Graph";
import SidePanel, { type Selection } from "@/components/SidePanel";
import { useCourseFetch } from "@/lib/useCourseFetch";
import {requestDocumentGeneration,watchDocumentGeneration} from '@/lib/documentGenerationClient';
import type {DocumentGenerationJob} from '@/lib/documentGeneration';
import SearchBar from "@/components/SearchBar";
import DocumentsPanel from "@/components/DocumentsPanel";
import BackupPanel from "@/components/BackupPanel";
import ModeToggle from "@/components/ModeToggle";
import type { ChatTurn } from "@/lib/llm";
import type { MasteryInfo } from "@/lib/mastery";
import { findOrphans, findRootNotions } from "@/lib/graphHealth";
import { useDragResize } from "@/lib/useDragResize";
import {
  colorForDomain,
  type Document,
  type GenerationMode,
  type Link,
  type Notion,
} from "@/lib/types";

interface DocumentWithStats extends Document {
  passageCount: number;
  generatedPassageCount: number;
  generationJob?:DocumentGenerationJob;
}

interface HomeClientProps {
  courseId:string;
  initialNotions: Notion[];
  initialLinks: Link[];
  initialDocuments: DocumentWithStats[];
  initialMastery: Record<string, MasteryInfo>;
  llmConfigured: boolean;
  providerLabel: string;
}

type SelectionRef = { kind: "node"; id: string } | { kind: "edge"; id: string };

function normalizeLabel(label: string): string {
  return label.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

// Flags a likely duplicate so the UI can offer a one-click merge — mainly
// useful after decompose/generate runs on a weaker local model, which
// sometimes proposes a notion that already exists elsewhere in the graph.
// Deliberately strict (exact match after normalizing case/punctuation only):
// a fuzzier word-overlap heuristic also caught legitimate specializations
// like "Catastrophe Excess of Loss" as a "duplicate" of "Excess of Loss",
// which is actively harmful to suggest merging away. The always-available
// manual "merge with..." search in the side panel covers near-duplicates
// this conservative check misses.
function findLikelyDuplicate(notion: Notion, all: Notion[]): Notion | null {
  const norm = normalizeLabel(notion.label);
  if (norm.length === 0) return null;
  return all.find((n) => n.id !== notion.id && normalizeLabel(n.label) === norm) ?? null;
}

// Every group of 2+ notions sharing the same normalized label — same
// conservative exact-match rule as findLikelyDuplicate, just across the
// whole graph at once instead of one selected notion at a time.
function findDuplicateGroups(notions: Notion[], links: Link[]): Notion[][] {
  const byNorm = new Map<string, Notion[]>();
  for (const n of notions) {
    const norm = normalizeLabel(n.label);
    if (!norm) continue;
    const list = byNorm.get(norm) ?? [];
    list.push(n);
    byNorm.set(norm, list);
  }
  const linkCount = new Map<string, number>();
  for (const l of links) {
    linkCount.set(l.source, (linkCount.get(l.source) ?? 0) + 1);
    linkCount.set(l.target, (linkCount.get(l.target) ?? 0) + 1);
  }
  return [...byNorm.values()]
    .filter((group) => group.length > 1)
    // Most-connected notion in each group first — it becomes the merge
    // target, so the richer/better-linked copy is the one that survives.
    .map((group) => [...group].sort((a, b) => (linkCount.get(b.id) ?? 0) - (linkCount.get(a.id) ?? 0)));
}

export default function HomeClient({
  courseId,
  initialNotions,
  initialLinks,
  initialDocuments,
  initialMastery,
  llmConfigured,
  providerLabel,
}: HomeClientProps) {
  const fetch=useCourseFetch(courseId);
  const [notions, setNotions] = useState<Notion[]>(initialNotions);
  const [links, setLinks] = useState<Link[]>(initialLinks);
  const [documents, setDocuments] = useState<DocumentWithStats[]>(initialDocuments);
  const generationWatch=useRef<{id:string;courseId:string;canceled:boolean}|null>(null);
  // Server-fetched on every load of this page (force-dynamic) — no client
  // state needed since mastery only changes via Study/Interview, both
  // separate routes the user navigates back from.
  const mastery = initialMastery;
  const [selection, setSelection] = useState<SelectionRef | null>(null);
  const [query, setQuery] = useState("");
  const [mode, setMode] = useState<GenerationMode>("strict");
  const [flowInstance, setFlowInstance] = useState<ReactFlowInstance | null>(null);
  const [documentsOpen, setDocumentsOpen] = useState(false);
  const [backupOpen, setBackupOpen] = useState(false);

  // Escape deselects the current node/edge (closing the side panel) — the
  // only other way to do that today is clicking empty graph space, which
  // isn't always reachable without losing your pan/zoom position.
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      const target = e.target as HTMLElement | null;
      if (target && (target.tagName === "INPUT" || target.tagName === "TEXTAREA" || target.isContentEditable)) return;
      setSelection(null);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  // Direct-manipulation resize handles on the actual bars, not a settings
  // menu — drag the header's bottom edge up to shrink it (more room for the
  // map), drag the side panel's left edge to make it wider or narrower.
  const headerContentRef = useRef<HTMLElement>(null);
  const headerResize = useDragResize({ storageKey: "ui.headerHeight", axis: "y", min: 0, max: 260, initial: null });
  const sidePanelResize = useDragResize({
    storageKey: "ui.sidePanelWidth",
    axis: "x",
    min: 280,
    max: 800,
    initial: 420,
    invert: true,
  });
  // Plain inline styles + React-driven hover (not Tailwind classes) for the
  // two grip indicators — arbitrary-value width/background utility classes
  // on these particular bare <span>s weren't being generated into the CSS
  // bundle for reasons not worth chasing further; inline style sidesteps it.
  const [headerHandleHover, setHeaderHandleHover] = useState(false);
  const [sidePanelHandleHover, setSidePanelHandleHover] = useState(false);
  const gripLineStyle = (hovered: boolean, horizontal: boolean) => ({
    width: horizontal ? 32 : 2,
    height: horizontal ? 2 : 32,
    borderRadius: 999,
    backgroundColor: hovered ? "#c18a38" : "#696A61",
  });

  const [decomposing, setDecomposing] = useState(false);
  const [decomposeError, setDecomposeError] = useState<string | null>(null);

  const [goingFurther, setGoingFurther] = useState(false);
  const [goFurtherError, setGoFurtherError] = useState<string | null>(null);

  const [adeptGenerating, setAdeptGenerating] = useState(false);
  const [adeptError, setAdeptError] = useState<string | null>(null);

  const [chatByNotion, setChatByNotion] = useState<Record<string, ChatTurn[]>>({});
  const [chatLoading, setChatLoading] = useState(false);

  const [uploadError, setUploadError] = useState<string | null>(null);
  const [generatingId, setGeneratingId] = useState<string | null>(null);
  const [generateError, setGenerateError] = useState<string | null>(null);
  const [generateInfo, setGenerateInfo] = useState<string | null>(null);

  const [undoAction, setUndoAction] = useState<{ message: string; perform: () => Promise<void> } | null>(
    null
  );

  useEffect(() => {
    if (!undoAction) return;
    const t = setTimeout(() => setUndoAction(null), 8000);
    return () => clearTimeout(t);
  }, [undoAction]);

  const selectionForPanel: Selection | null = useMemo(() => {
    if (!selection) return null;
    if (selection.kind === "node") {
      const notion = notions.find((n) => n.id === selection.id);
      return notion ? { kind: "node", notion } : null;
    }
    const link = links.find((l) => l.id === selection.id);
    if (!link) return null;
    const source = notions.find((n) => n.id === link.source);
    const target = notions.find((n) => n.id === link.target);
    if (!source || !target) return null;
    return { kind: "edge", link, source, target };
  }, [selection, notions, links]);

  const similarNotion = useMemo(() => {
    if (!selectionForPanel || selectionForPanel.kind !== "node") return null;
    return findLikelyDuplicate(selectionForPanel.notion, notions);
  }, [selectionForPanel, notions]);

  const refreshGraph = async () => {
    const res = await fetch("/api/graph");
    if (!res.ok) return;
    const data = (await res.json()) as { notions: Notion[]; links: Link[] };
    setNotions(data.notions);
    setLinks(data.links);
  };

  // Just selects — no viewport change. Used for a direct click on a node
  // already visible in the graph, so the view stays exactly where the user
  // left it instead of re-centering/re-zooming on every click.
  const selectNode = (id: string) => {
    setSelection({ kind: "node", id });
  };

  // Selects AND jumps the viewport to the node — for when the user doesn't
  // already know where it is on screen (search results), where re-centering
  // AND re-zooming to a sane level is the actual point.
  const focusNode = useCallback(
    (id: string) => {
      setSelection({ kind: "node", id });
      flowInstance?.fitView({ nodes: [{ id }], duration: 500, maxZoom: 1.2 });
    },
    [flowInstance]
  );

  const selectEdge = (id: string) => {
    setSelection({ kind: "edge", id });
  };

  const toggleStatus = async (notionId: string) => {
    const notion = notions.find((n) => n.id === notionId);
    if (!notion) return;
    const nextStatus = notion.status === "draft" ? "validated" : "draft";
    setNotions((prev) => prev.map((n) => (n.id === notionId ? { ...n, status: nextStatus } : n)));
    await fetch(`/api/notions/${notionId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status: nextStatus }),
    });
  };

  const decompose = async (notionId: string) => {
    setDecomposing(true);
    setDecomposeError(null);
    try {
      const res = await fetch(`/api/notions/${notionId}/decompose`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mode }),
      });
      const data = await res.json();
      if (!res.ok) {
        setDecomposeError(data.error ?? "Failed to decompose");
        return;
      }
      setNotions((prev) => [...prev, ...data.notions]);
      setLinks((prev) => [...prev, ...data.links]);
      const newIds: string[] = data.notions.map((n: Notion) => n.id);
      if (newIds.length === 0) {
        setDecomposeError("Nothing new to add — already covered by existing notions.");
      } else {
        setUndoAction({
          message: `Added ${newIds.length} notion${newIds.length > 1 ? "s" : ""}`,
          perform: async () => {
            for (const id of newIds) {
              await fetch(`/api/notions/${id}`, { method: "DELETE" });
            }
            setUndoAction(null);
            await refreshGraph();
          },
        });
      }
    } catch {
      setDecomposeError("Network error while contacting the model.");
    } finally {
      setDecomposing(false);
    }
  };

  const goFurther = async (notionId: string) => {
    setGoingFurther(true);
    setGoFurtherError(null);
    try {
      const res = await fetch(`/api/notions/${notionId}/go-further`, { method: "POST" });
      const data = await res.json();
      if (!res.ok) {
        setGoFurtherError(data.error ?? "Failed to generate the go-further note");
        return;
      }
      setNotions((prev) => prev.map((n) => (n.id === notionId ? { ...n, goFurther: data.goFurther } : n)));
    } catch {
      setGoFurtherError("Network error while contacting the model.");
    } finally {
      setGoingFurther(false);
    }
  };

  const generateAdept = async (notionId: string) => {
    setAdeptGenerating(true);
    setAdeptError(null);
    try {
      const res = await fetch(`/api/notions/${notionId}/adept`, { method: "POST" });
      const data = await res.json();
      if (!res.ok) {
        setAdeptError(data.error ?? "Failed to generate the ADEPT breakdown");
        return;
      }
      setNotions((prev) => prev.map((n) => (n.id === notionId ? { ...n, adept: data.adept } : n)));
    } catch {
      setAdeptError("Network error while contacting the model.");
    } finally {
      setAdeptGenerating(false);
    }
  };

  const deleteNotionHandler = async (notionId: string) => {
    const notionSnapshot = notions.find((n) => n.id === notionId);
    const linksSnapshot = links.filter((l) => l.source === notionId || l.target === notionId);

    await fetch(`/api/notions/${notionId}`, { method: "DELETE" });
    setChatByNotion((prev) => {
      const next = { ...prev };
      delete next[notionId];
      return next;
    });
    if (selection?.kind === "node" && selection.id === notionId) {
      setSelection(null);
    }
    await refreshGraph();

    if (notionSnapshot) {
      setUndoAction({
        message: `Deleted "${notionSnapshot.label}"`,
        perform: async () => {
          await fetch("/api/notions/restore", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ notion: notionSnapshot, links: linksSnapshot }),
          });
          setUndoAction(null);
          await refreshGraph();
        },
      });
    }
  };

  const mergeNotionHandler = async (fromId: string, intoId: string) => {
    await fetch(`/api/notions/${fromId}/merge`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ intoId }),
    });
    setChatByNotion((prev) => {
      const next = { ...prev };
      delete next[fromId];
      return next;
    });
    setSelection({ kind: "node", id: intoId });
    await refreshGraph();
  };

  const [mergeAllConfirming, setMergeAllConfirming] = useState(false);
  const [mergingAll, setMergingAll] = useState(false);
  const duplicateGroups = useMemo(() => findDuplicateGroups(notions, links), [notions, links]);
  const orphanNotions = useMemo(() => findOrphans(notions, links), [notions, links]);
  const rootNotions = useMemo(() => findRootNotions(notions, links), [notions, links]);
  const [consolidating, setConsolidating] = useState(false);
  const consolidateRootsHandler = async () => {
    setConsolidating(true);
    try {
      await fetch("/api/graph/consolidate-roots", { method: "POST" });
      await refreshGraph();
    } finally {
      setConsolidating(false);
    }
  };

  const mergeAllDuplicates = async () => {
    setMergingAll(true);
    try {
      for (const group of duplicateGroups) {
        const [into, ...rest] = group;
        for (const dup of rest) {
          await fetch(`/api/notions/${dup.id}/merge`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ intoId: into.id }),
          });
        }
      }
      await refreshGraph();
    } finally {
      setMergingAll(false);
      setMergeAllConfirming(false);
    }
  };

  const sendChat = async (text: string) => {
    if (!selection || selection.kind !== "node") return;
    const notionId = selection.id;
    const history = chatByNotion[notionId] ?? [];
    const withUser = [...history, { role: "user" as const, content: text }];
    setChatByNotion((prev) => ({ ...prev, [notionId]: withUser }));
    setChatLoading(true);
    try {
      const res = await fetch(`/api/notions/${notionId}/chat`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mode, messages: withUser }),
      });
      const data = await res.json();
      const reply = res.ok ? data.reply : `Error: ${data.error ?? "request failed"}`;
      setChatByNotion((prev) => ({
        ...prev,
        [notionId]: [...withUser, { role: "assistant", content: reply,sources:data.sources,outsideKnowledge:data.outsideKnowledge }],
      }));
    } catch {
      setChatByNotion((prev) => ({
        ...prev,
        [notionId]: [...withUser, { role: "assistant", content: "Error: network request failed." }],
      }));
    } finally {
      setChatLoading(false);
    }
  };

  const uploadDocument = async (file: File, title: string) => {
    setUploadError(null);
    const formData = new FormData();
    formData.append("file", file);
    if (title.trim()) formData.append("title", title.trim());
    try {
      const res = await fetch("/api/documents", { method: "POST", body: formData });
      const data = await res.json();
      if (!res.ok) {
        setUploadError(data.error ?? "Upload failed");
        return;
      }
      setDocuments((prev) => [data.document, ...prev]);
    } catch {
      setUploadError("Network error during upload.");
    }
  };

  const observeGeneration=useCallback(async(job:DocumentGenerationJob)=>{
    if(generationWatch.current?.id===job.id && !generationWatch.current.canceled)return;
    if(generationWatch.current)generationWatch.current.canceled=true;
    const watch={id:job.id,courseId,canceled:false};generationWatch.current=watch;
    setGeneratingId(job.documentId);setGenerateError(null);
    let lastUpdate='';
    try {
      await watchDocumentGeneration(fetch,job,async current=>{
        if(watch.canceled || current.updatedAt===lastUpdate)return;
        lastUpdate=current.updatedAt;
        const running=current.status==='running';
        setGenerateInfo(running
          ? `Generating: ${current.completedPages}/${current.totalPages} pages ready, ${current.cardsCreated} new cards. ${Object.entries(current.activeStages??{}).map(([page,stage])=>`Slide ${page}: ${stage}`).join(' · ') || 'Processing the remaining pages automatically.'}`
          : current.status==='complete'
            ? `Done: ${current.completedPages} pages processed, ${current.cardsCreated} new cards.`
            : `${current.completedPages}/${current.totalPages} pages ready. ${current.reviewPages.length} page(s) need review; accepted notes and cards are saved.`);
        if(!running && current.status!=='complete')setGenerateError(current.error??current.warnings.slice(0,3).join(' · '));
        if(current.attemptedPages.length || !running){
          const [graphRes,docsRes]=await Promise.all([fetch('/api/graph'),fetch('/api/documents')]);
          const graph=graphRes.ok?await graphRes.json():null,docs=docsRes.ok?await docsRes.json():null;
          if(watch.canceled)return;
          if(graph){setNotions(graph.notions);setLinks(graph.links);}
          if(docs)setDocuments(docs.documents);
        }
      },()=>watch.canceled);
    }catch(error){if(!watch.canceled)setGenerateError(error instanceof Error?error.message:'Unable to read generation progress.');}
    finally {if(generationWatch.current===watch){generationWatch.current=null;setGeneratingId(null);}}
  },[courseId,fetch]);

  useEffect(()=>{
    let canceled=false;
    void fetch('/api/documents').then(async response=>{
      if(!response.ok)return;
      const data=await response.json() as {documents:DocumentWithStats[]};
      if(canceled)return;
      setDocuments(data.documents);
      const running=data.documents.find(d=>d.generationJob?.status==='running');
      if(running?.generationJob)void observeGeneration(running.generationJob);
    }).catch(()=>{});
    return ()=>{canceled=true;if(generationWatch.current?.courseId===courseId)generationWatch.current.canceled=true;};
  },[courseId,fetch,observeGeneration]);

  const generateFromDocument=async(documentId:string,enrichment=false)=>{
    setGeneratingId(documentId);setGenerateError(null);setGenerateInfo(null);
    try {await observeGeneration(await requestDocumentGeneration(fetch,documentId,{mode,enrichment}));}
    catch(error){setGenerateError(error instanceof Error?error.message:'Could not start generation.');setGeneratingId(null);}
  };

  const deleteDocumentHandler = async (documentId: string) => {
    await fetch(`/api/documents/${documentId}`, { method: "DELETE" });
    setDocuments((prev) => prev.filter((d) => d.id !== documentId));
    // A deleted document's citations disappear from any notion that had
    // them, so refresh the graph to pick that up.
    await refreshGraph();
  };

  const selectedNodeId = selection?.kind === "node" ? selection.id : null;
  const selectedEdgeId = selection?.kind === "edge" ? selection.id : null;
  const chatMessages = selectedNodeId ? chatByNotion[selectedNodeId] ?? [] : [];

  return (
    <div className="flex h-full flex-col bg-[#1a1a1b]">
      <div
        style={headerResize.size === null ? undefined : { height: headerResize.size, overflow: "hidden" }}
        className="shrink-0"
      >
      <header
        ref={headerContentRef}
        className="flex flex-col gap-4 border-b border-[#423e42] bg-[#201f21] px-6 py-4"
      >
        <div className="flex items-center justify-between">
          <div>
            <h1 className="font-display text-lg font-medium tracking-wide text-accent-200">Encyclopedia</h1>
            <p className="text-xs text-[#696A61]">
              {notions.length} notions · {links.length} links · {documents.length} documents
              {" · "}
              {llmConfigured ? `AI: ${providerLabel}` : "AI features need OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL"}
            </p>
          </div>
          <div className="flex items-center gap-2">
            {rootNotions.length > 2 && (
              <button
                onClick={consolidateRootsHandler}
                disabled={consolidating}
                title="Use AI to arrange top-level notions into subject categories. Changes the map organization; does not verify or improve the course content."
                className="rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-1.5 text-xs text-amber-300 hover:bg-amber-500/20 disabled:cursor-not-allowed disabled:opacity-40"
              >
                {consolidating ? "Organizing…" : "Organize map into categories"}
              </button>
            )}
            {orphanNotions.length > 0 && (
              <button
                onClick={() => focusNode(orphanNotions[0].id)}
                title={`Not connected to anything else in the map: ${orphanNotions.map((n) => n.label).join(", ")}`}
                className="rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-1.5 text-xs text-amber-300 hover:bg-amber-500/20"
              >
                {orphanNotions.length} isolated
              </button>
            )}
            {duplicateGroups.length > 0 && (
              <div className="relative">
                <button
                  onClick={() => setMergeAllConfirming((v) => !v)}
                  className="rounded-md border border-amber-500/40 bg-amber-500/10 px-3 py-1.5 text-xs text-amber-300 hover:bg-amber-500/20"
                >
                  Merge duplicates ({duplicateGroups.length})
                </button>
                {mergeAllConfirming && (
                  <div className="absolute right-0 z-50 mt-2 w-80 rounded-md border border-[#423e42] bg-[#201f21] p-3 shadow-xl">
                    <p className="mb-2 text-xs text-[#8F8978]">
                      Merge {duplicateGroups.reduce((sum, g) => sum + g.length - 1, 0)} notion(s) into their most-connected
                      duplicate:
                    </p>
                    <ul className="mb-3 max-h-40 space-y-1 overflow-y-auto text-xs text-[#696A61]">
                      {duplicateGroups.map((group) => (
                        <li key={group[0].id}>
                          {group.slice(1).map((n) => n.label).join(", ")} → <span className="text-[#8F8978]">{group[0].label}</span>
                        </li>
                      ))}
                    </ul>
                    <div className="flex gap-2">
                      <button
                        onClick={mergeAllDuplicates}
                        disabled={mergingAll}
                        className="rounded border border-amber-500/40 bg-amber-500/20 px-2 py-1 text-xs text-amber-200 hover:bg-amber-500/30 disabled:opacity-50"
                      >
                        {mergingAll ? "Merging…" : "Merge all"}
                      </button>
                      <button
                        onClick={() => setMergeAllConfirming(false)}
                        className="rounded border border-[#423e42] px-2 py-1 text-xs text-[#8F8978] hover:bg-[#322f33]"
                      >
                        Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>
            )}
            <button
              onClick={() => setBackupOpen(true)}
              className="rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33]"
            >
              Backup
            </button>
          </div>
        </div>

        <div className="grid grid-cols-[1fr_auto_1.35fr] items-center gap-8">
          <div className="min-w-0">
            <ModeToggle mode={mode} onChange={setMode} />
          </div>

          <div className="flex items-center gap-3">
            <NextLink
              href="/study"
              className="rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33]"
            >
              Study
            </NextLink>
            <NextLink
              href="/interview"
              className="rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33]"
            >
              Interview
            </NextLink>
          </div>

          <div className="flex min-w-0 items-center justify-end gap-4">
            <div className="flex items-center gap-3 border-l border-[#423e42] pl-4">
              <NextLink
                href="/progress"
                className="rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33]"
              >
                Progress
              </NextLink>
              <NextLink
                href="/browse"
                className="rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33]"
              >
                Browse
              </NextLink>
              <button
                onClick={() => setDocumentsOpen(true)}
                className="rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33]"
              >
                Documents
              </button>
            </div>
            <SearchBar notions={notions} query={query} onQueryChange={setQuery} onPickNotion={focusNode} />
          </div>
        </div>
      </header>
      </div>
      <div
        onPointerDown={(e) => headerResize.onDragStart(e, () => headerContentRef.current?.scrollHeight ?? 140)}
        onMouseEnter={() => setHeaderHandleHover(true)}
        onMouseLeave={() => setHeaderHandleHover(false)}
        title="Drag to resize"
        className="flex h-2 w-full shrink-0 cursor-row-resize flex-col items-center justify-center gap-0.5 bg-[#201f21]"
      >
        <span style={gripLineStyle(headerHandleHover, true)} />
        <span style={gripLineStyle(headerHandleHover, true)} />
      </div>

      {decomposeError && (
        <div className="border-b border-red-500/20 bg-red-500/10 px-5 py-2 text-xs text-red-300">
          {decomposeError}
        </div>
      )}
      {goFurtherError && (
        <div className="border-b border-red-500/20 bg-red-500/10 px-5 py-2 text-xs text-red-300">
          {goFurtherError}
        </div>
      )}
      {adeptError && (
        <div className="border-b border-red-500/20 bg-red-500/10 px-5 py-2 text-xs text-red-300">
          {adeptError}
        </div>
      )}

      {undoAction && (
        <div className="fixed bottom-5 left-1/2 z-[100] flex -translate-x-1/2 items-center gap-3 rounded-md border border-[#423e42] bg-[#201f21] px-4 py-2.5 text-sm text-[#D4C6A6] shadow-2xl">
          <span>{undoAction.message}</span>
          <button
            onClick={() => undoAction.perform()}
            className="rounded px-2 py-1 text-xs font-medium text-[#1c140d] bg-accent-300 hover:bg-accent-200"
          >
            Undo
          </button>
        </div>
      )}

      <div className="flex flex-1 overflow-hidden">
        <div className="relative flex-1">
          <Graph
            notions={notions}
            links={links}
            mastery={mastery}
            selectedNodeId={selectedNodeId}
            selectedEdgeId={selectedEdgeId}
            searchQuery={query}
            onSelectNode={selectNode}
            onSelectEdge={selectEdge}
            onInit={setFlowInstance}
            onClearSearch={() => setQuery("")}
          />
          <Legend notions={notions} />
        </div>
        <div
          onPointerDown={sidePanelResize.onDragStart}
          onMouseEnter={() => setSidePanelHandleHover(true)}
          onMouseLeave={() => setSidePanelHandleHover(false)}
          title="Drag to resize"
          className="flex w-2 shrink-0 cursor-col-resize flex-row items-center justify-center gap-0.5 bg-[#201f21]"
        >
          <span style={gripLineStyle(sidePanelHandleHover, false)} />
          <span style={gripLineStyle(sidePanelHandleHover, false)} />
        </div>
        <div style={{ width: sidePanelResize.size ?? 420 }} className="h-full shrink-0">
          <SidePanel
            key={selection ? `${selection.kind}-${selection.id}` : "none"}
            selection={selectionForPanel}
            courseId={courseId}
            documents={documents}
            mastery={mastery}
            llmConfigured={llmConfigured}
            decomposing={decomposing}
            onDecompose={decompose}
            goingFurther={goingFurther}
            onGoFurther={goFurther}
            adeptGenerating={adeptGenerating}
            onGenerateAdept={generateAdept}
            onToggleStatus={toggleStatus}
            onEditNotion={updated=>setNotions(previous=>previous.map(n=>n.id===updated.id?updated:n))}
            chatMessages={chatMessages}
            chatLoading={chatLoading}
            onSendChat={sendChat}
            onDelete={deleteNotionHandler}
            similarNotion={similarNotion}
            onMerge={mergeNotionHandler}
            allNotions={notions}
          />
        </div>
      </div>

      <DocumentsPanel
        open={documentsOpen}
        onClose={() => setDocumentsOpen(false)}
        documents={documents}
        llmConfigured={llmConfigured}
        onUpload={uploadDocument}
        onGenerate={generateFromDocument}
        mode={mode}
        onDelete={deleteDocumentHandler}
        generatingId={generatingId}
        uploadError={uploadError}
        generateError={generateError}
        generateInfo={generateInfo}
      />

      <BackupPanel courseId={courseId} open={backupOpen} onClose={() => setBackupOpen(false)} />
    </div>
  );
}

function Legend({ notions }: { notions: Notion[] }) {
  const domains = [...new Set(notions.map((n) => n.domain))].sort();
  return (
    <div
      title="Each color is a thematic area of the subject (like a course chapter) that the AI grouped notions into — not a fixed taxonomy, just whatever areas this course's own content actually covers."
      className="pointer-events-auto absolute bottom-4 left-4 rounded-lg border border-[#423e42] bg-[#201f21]/90 p-3 text-xs shadow-lg backdrop-blur"
    >
      {domains.map((domain) => {
        const color = colorForDomain(domain);
        return (
          <div key={domain} className="flex items-center gap-1.5 py-0.5">
            <span className="h-2 w-2 rounded-full" style={{ backgroundColor: color, boxShadow: `0 0 6px ${color}99` }} />
            <span className="text-[#8F8978]">{domain}</span>
          </div>
        );
      })}
    </div>
  );
}

"use client";

import { useEffect, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { Background, BackgroundVariant, Controls, ReactFlow, type Node, type ReactFlowInstance } from "@xyflow/react";
import "@xyflow/react/dist/style.css";
import { mapOverview } from "@/lib/mapOverview";
import { mappingKeyboardTarget } from "@/lib/mappingKeyboard";
import { colorForDomain, type Link, type Notion } from "@/lib/types";
import type { MasteryInfo } from "@/lib/mastery";
import { MASTERY_COLORS } from '@/components/NotionNode';

interface GraphProps {
  notions: Notion[];
  links: Link[];
  mastery: Record<string, MasteryInfo>;
  selectedNodeId: string | null;
  selectedEdgeId: string | null;
  searchQuery: string;
  onSelectNode: (id: string) => void;
  onSelectEdge: (id: string) => void;
  onInit: (instance: ReactFlowInstance) => void;
  onClearSearch: () => void;
}

const PAGE_SIZE = 16;

export default function Graph({ notions, links, mastery, selectedNodeId, searchQuery, onSelectNode, onSelectEdge, onInit, onClearSearch }: GraphProps) {
  const map = useMemo(() => mapOverview(notions, links), [notions, links]);
  const [path, setPath] = useState<string[]>([]);
  const [page, setPage] = useState(0);
  const container=useRef<HTMLDivElement>(null);
  const keyboardSelection=useRef(selectedNodeId);
  useEffect(()=>{keyboardSelection.current=selectedNodeId;},[selectedNodeId]);
  const validPath = path.filter(id => map.byId.has(id));
  const current = validPath.at(-1);
  const query = searchQuery.trim().toLocaleLowerCase();
  const ids = query
    ? notions.filter(n => n.label.toLocaleLowerCase().includes(query)).map(n => n.id)
    : current ? map.children.get(current) ?? [] : map.roots;
  const pageCount = Math.max(1, Math.ceil(ids.length / PAGE_SIZE));
  const activePage = Math.min(page, pageCount - 1);
  const visible = ids.slice(activePage * PAGE_SIZE, (activePage + 1) * PAGE_SIZE);
  // Keep the same column count on the final page, so Up/Down retain their
  // spatial meaning when a branch spans several pages.
  const columns = Math.min(ids.length > 9 ? 4 : 3, Math.max(1, ids.length));
  const height = current || query ? 185 : 250;
  const connected = links.filter(link => (link.source === selectedNodeId || link.target === selectedNodeId) && map.byId.has(link.source) && map.byId.has(link.target));
  const open = (id: string) => {
    keyboardSelection.current=id;
    onSelectNode(id);
    container.current?.focus({preventScroll:true});
    if (map.children.get(id)?.length) {
      const existing = validPath.indexOf(id);
      setPath(existing >= 0 ? validPath.slice(0, existing + 1) : [...validPath, id]);
      setPage(0);
      if (query) onClearSearch();
    }
  };
  const onKeyDown=(event:KeyboardEvent<HTMLDivElement>)=>{
    if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Enter','Backspace','Escape'].includes(event.key) || event.altKey || event.ctrlKey || event.metaKey || event.nativeEvent.isComposing)return;
    const target=event.target as HTMLElement;
    if(target.closest('input,textarea,select,[contenteditable="true"],a,summary') || target.closest('button') && !target.closest('[data-map-topic]'))return;
    if(event.key==='Escape' && !current)return;
    event.preventDefault();event.stopPropagation();
    const selected=keyboardSelection.current;
    if(event.key==='Backspace' || event.key==='Escape') {
      if(!event.repeat && current && (!query || event.key==='Escape')){
        const parent=validPath.at(-2),siblings=parent?map.children.get(parent)??[]:map.roots;
        setPath(validPath.slice(0,-1));setPage(Math.max(0,Math.floor(siblings.indexOf(current)/PAGE_SIZE)));
        if(query)onClearSearch();
        keyboardSelection.current=current;onSelectNode(current);container.current?.focus({preventScroll:true});
      }
      return;
    }
    if(event.key==='Enter') {
      // Holding Enter must not drill through several nested branches.
      if(!event.repeat && selected && visible.includes(selected))open(selected);
      return;
    }
    const next=mappingKeyboardTarget(ids,selected,event.key,columns);
    if(!next)return;
    keyboardSelection.current=next;
    setPage(Math.floor(ids.indexOf(next)/PAGE_SIZE));
    onSelectNode(next);
    // The compact grid is already in view. Keep its camera still as selection
    // moves, and preserve a synchronous cursor during held/repeated keypresses.
    container.current?.focus({preventScroll:true});
  };
  const nodes: Node[] = visible.map((id, index) => {
    const notion = map.byId.get(id)!;
    const children = map.children.get(id) ?? [];
    const color = colorForDomain(notion.domain);
    return {
      id,
      position: { x: (index % columns) * 270, y: Math.floor(index / columns) * (height + 25) },
      style: { width: 245, height, padding: 0, border: "none", background: "transparent" },
      data: { label: (
        <button data-map-topic={id} aria-label={`Open ${notion.label}`} aria-pressed={selectedNodeId===id} onFocus={()=>{keyboardSelection.current=id;onSelectNode(id);}} onClick={event => { if (event.detail === 0) { event.stopPropagation(); open(id); } }} className="block h-full w-full rounded-xl border bg-[#28262a] p-4 text-left hover:bg-[#302d32]" style={{ borderLeftColor: selectedNodeId === id ? color : "#423e42", borderRightColor: selectedNodeId === id ? color : "#423e42", borderBottomColor: selectedNodeId === id ? color : "#423e42", borderTopColor: color, borderTopWidth: 3 }}>
          <div className="mb-2 text-[15px] font-semibold leading-snug text-[#D4C6A6]">{notion.label.replace(/^Chapter:\s*/i, "")} <span role="img" aria-label={`Mastery: ${mastery[id]?.level ?? 'unknown'}`} title={`Mastery: ${mastery[id]?.level ?? 'unknown'}${mastery[id]?.weakestDimension ? ` · Next: ${mastery[id].weakestDimension}` : ''}`} className="ml-1 inline-block h-2.5 w-2.5 rounded-full" style={{backgroundColor: MASTERY_COLORS[mastery[id]?.level ?? 'unknown']}}/></div>
          {children.length ? (
            <>
              {notion.layer === 'organizer' && !notion.definition.startsWith('Semantic navigation group:') ? <p className="whitespace-pre-line text-xs leading-relaxed text-[#8F8978]">{notion.definition}</p> : !current && !query && <div className="space-y-1 text-xs leading-snug text-[#8F8978]">
                {children.slice(0, 6).map(child => <div key={child}>{map.byId.get(child)?.label}</div>)}
              </div>}
              {current && notion.layer !== 'organizer' && <p className="line-clamp-3 text-xs leading-relaxed text-[#8F8978]">{notion.definition}</p>}
              <div className="mt-2 text-[11px]" style={{ color }}>{children.length} subtopics · Open →</div>
            </>
          ) : <p className="line-clamp-3 text-xs leading-relaxed text-[#8F8978]">{notion.definition}</p>}
        </button>
      ) },
    };
  });

  return (
    <div ref={container} tabIndex={0} aria-label="Course mapping" aria-keyshortcuts="ArrowUp ArrowDown ArrowLeft ArrowRight Enter Backspace Escape" onKeyDownCapture={onKeyDown} onPointerDownCapture={event=>{if(!(event.target as HTMLElement).closest('button,input,textarea,select,a,summary'))container.current?.focus({preventScroll:true});}} className="flex h-full flex-col outline-none" data-testid="compact-mapping">
      <nav aria-label="Mapping path" className="relative z-20 flex min-h-11 flex-wrap items-center gap-2 border-b border-[#423e42] px-4 py-2 text-xs text-[#8F8978]">
        <button className="hover:text-[#D4C6A6]" onClick={() => { setPath([]); setPage(0); onClearSearch(); }}>Overview</button>
        {validPath.map((id, index) => <span className="flex items-center gap-2" key={id}>› <button className="hover:text-[#D4C6A6]" onClick={() => { setPath(validPath.slice(0, index + 1)); setPage(0); }}>{map.byId.get(id)?.label}</button></span>)}
        <span className="ml-auto">{query ? `${ids.length} results` : current ? `${ids.length} subtopics` : `${ids.length} main topics`}</span>
        {connected.length > 0 && <details key={selectedNodeId} className="relative">
          <summary className="cursor-pointer">Connections ({connected.length})</summary>
          <div className="absolute right-0 top-7 max-h-64 w-72 overflow-y-auto rounded border border-[#423e42] bg-[#201f21] p-2 shadow-xl">
            {connected.map(link => <button key={link.id} className="block w-full rounded p-2 text-left hover:bg-[#302d32]" onClick={() => onSelectEdge(link.id)}>
              <span className="block text-[#D4C6A6]">{map.byId.get(link.source)?.label} → {map.byId.get(link.target)?.label}</span>
              <span className="text-[10px]">{link.type.replace("-", " ")}</span>
            </button>)}
          </div>
        </details>}
        {pageCount > 1 && <><button aria-label="Previous topics" disabled={!activePage} onClick={() => setPage(activePage - 1)} className="px-2 disabled:opacity-30">←</button><span>{activePage + 1} / {pageCount}</span><button aria-label="Next topics" disabled={activePage + 1 === pageCount} onClick={() => setPage(activePage + 1)} className="px-2 disabled:opacity-30">→</button></>}
      </nav>
      <div className="relative min-h-0 flex-1">
        <ReactFlow
          key={`${current ?? "overview"}:${activePage}:${query}:${visible.join(",")}`}
          nodes={nodes}
          edges={[]}
          onInit={onInit}
          onNodeClick={(_, node) => open(node.id)}
          colorMode="dark"
          nodesDraggable={false}
          nodesFocusable={false}
          nodesConnectable={false}
          panOnDrag={[0, 1, 2]}
          panOnScroll={false}
          zoomOnScroll
          zoomOnPinch
          selectionOnDrag={false}
          selectionKeyCode={null}
          paneClickDistance={5}
          nodeClickDistance={5}
          minZoom={0.2}
          maxZoom={2}
          fitView
          fitViewOptions={{ padding: 0.12, maxZoom: 1 }}
        >
          <Background variant={BackgroundVariant.Dots} gap={22} size={1.5} />
          <Controls showInteractive={false} />
          {!visible.length && <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-center text-center text-sm text-[#8F8978]">{query ? "No matching topics" : "Your mapping is empty. Open Documents to generate it. Your cards remain in Browse."}</div>}
        </ReactFlow>
      </div>
    </div>
  );
}

"use client";

import { useContext, useEffect, useMemo, useState } from "react";
import { StudySessionContext, useStudyState } from "@/lib/useStudySession";
import { useCourseFetch } from '@/lib/useCourseFetch';
import { colorForDomain, type Notion } from "@/lib/types";
import { EXPLAIN_LEVELS, EXPLAIN_LEVEL_LABELS, type ExplainLevel } from "@/lib/explain";
import type { PronunciationCard } from "@/lib/db";

interface ExplainTabProps {
  allNotions: Notion[];
  llmConfigured: boolean;
  onPracticePronunciation: (card: PronunciationCard) => void;
}

interface AttemptResult {
  id?: string;
  verdict: "pass" | "retry";
  feedback: string;
  coveredKeywords: string[];
  missingKeywords: string[];
  answerText: string;
  correctedText?: string;
  exampleAnswer?: string;
}

interface ExplainSetup {
  level: ExplainLevel;
  prompt: string;
  requiredKeywords: string[];
  history: AttemptResult[];
}

interface WritingPattern {
  name: string;
  example: string;
  betterVersion: string;
  why: string;
}

const restoreSelectedId = (value: unknown) => typeof value === "string" || value === null ? value : null;
const restoreLevel = (value: unknown): ExplainLevel | null => typeof value === "string" && EXPLAIN_LEVELS.includes(value as ExplainLevel) ? value as ExplainLevel : null;

export default function ExplainTab({ allNotions, llmConfigured, onPracticePronunciation }: ExplainTabProps) {
  const {courseId} = useContext(StudySessionContext);
  const fetch = useCourseFetch(courseId);
  const [query, setQuery] = useStudyState("explain-query", "");
  const [selectedId, setSelectedId] = useStudyState<string | null>("explain-notion", null, restoreSelectedId);
  const selected = allNotions.find((notion) => notion.id === selectedId) ?? null;
  const setSelected = (notion: Notion | null) => setSelectedId(notion?.id ?? null);
  const [level, setLevel] = useStudyState<ExplainLevel>("explain-level", "child", restoreLevel);
  const [setup, setSetup] = useState<ExplainSetup | null>(null);
  const [history, setHistory] = useState<AttemptResult[]>([]);
  const [answer, setAnswer] = useStudyState("explain-answer", "");
  const [unaided, setUnaided] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [passedLevels, setPassedLevels] = useState<Set<ExplainLevel>>(new Set());
  const [showWorkQuestions, setShowWorkQuestions] = useState(false);
  const [generatingPronunciation, setGeneratingPronunciation] = useState<Record<string, boolean>>({});
  const [patterns, setPatterns] = useState<WritingPattern[] | null>(null);
  const [patternsLoading, setPatternsLoading] = useState(false);
  const [patternsError, setPatternsError] = useState<string | null>(null);

  const matches = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return [];
    return allNotions.filter((n) => n.label.toLowerCase().includes(q)).slice(0, 8);
  }, [query, allNotions]);

  useEffect(() => {
    if (!selected) return;
    const controller = new AbortController();
    fetch(`/api/notions/${selected.id}/explain?level=${level}`, { signal: controller.signal })
      .then((r) => {
        if (!r.ok) throw new Error("Could not load this explanation.");
        return r.json();
      })
      .then((data: ExplainSetup) => {
        setSetup(data);
        setHistory(data.history);
        if (data.history.some((a) => a.verdict === "pass")) {
          setPassedLevels((prev) => new Set(prev).add(level));
        }
      })
      .catch((error) => {
        if (!controller.signal.aborted) setSubmitError(error instanceof Error ? error.message : "Could not load this explanation.");
      });
    return () => controller.abort();
  }, [selected, level, fetch]);

  const pickNotion = (n: Notion) => {
    setUnaided(false);
    setSelected(n);
    setLevel("child");
    setQuery("");
    setPassedLevels(new Set());
    setAnswer("");
    setSubmitError(null);
    setShowWorkQuestions(false);
  };

  const changeLevel = (lvl: ExplainLevel) => {
    setUnaided(false);
    setLevel(lvl);
    setAnswer("");
    setSubmitError(null);
  };

  const submit = async () => {
    if (!selected || answer.trim().length < 10) return;
    setSubmitting(true);
    setSubmitError(null);
    const answerText = answer;
    try {
      const res = await fetch(`/api/notions/${selected.id}/explain`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ level, text: answerText, unaided }),
      });
      const data = await res.json();
      if (!res.ok) {
        setSubmitError(data.error ?? "Grading failed.");
        return;
      }
      setHistory((prev) => [...prev, { ...data.attempt, answerText }]);
      setAnswer("");
      setUnaided(false);
      if (data.attempt.verdict === "pass") {
        setPassedLevels((prev) => new Set(prev).add(level));
      }
    } finally {
      setSubmitting(false);
    }
  };

  const practicePronunciation = async (attempt: AttemptResult) => {
    if (!selected || !attempt.correctedText) return;
    const key = attempt.id ?? attempt.answerText;
    setGeneratingPronunciation((prev) => ({ ...prev, [key]: true }));
    try {
      const res = await fetch("/api/pronunciation/generate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          text: attempt.correctedText,
          notionId: selected.id,
          sourceAttemptId: attempt.id,
        }),
      });
      const data = await res.json();
      if (res.ok) {
        onPracticePronunciation(data.card);
      }
    } finally {
      setGeneratingPronunciation((prev) => ({ ...prev, [key]: false }));
    }
  };

  const analyzePatterns = async () => {
    setPatternsLoading(true);
    setPatternsError(null);
    try {
      const res = await fetch("/api/explain/patterns");
      const data = await res.json();
      if (!res.ok) {
        setPatternsError(data.error ?? "Could not analyze patterns.");
        return;
      }
      setPatterns(data.patterns);
    } finally {
      setPatternsLoading(false);
    }
  };

  if (!selected) {
    return (
      <div className="mx-auto max-w-lg px-6 py-10">
        <p className="mb-4 text-sm text-[#8F8978]">
          Pick a notion to explain. You&apos;ll write it three ways — to a child, to a non-expert
          colleague, then to a fellow practitioner — and get corrected at each level.
        </p>
        <input
          autoFocus
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search a notion…"
          className="w-full rounded-md border border-[#423e42] bg-[#28262a] px-3 py-2 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
        />
        {matches.length > 0 && (
          <ul className="mt-2 space-y-1 rounded-md border border-[#423e42] bg-[#28262a]">
            {matches.map((n) => (
              <li key={n.id}>
                <button
                  onClick={() => pickNotion(n)}
                  className="flex w-full items-center gap-2 px-3 py-2 text-left text-sm text-[#8F8978] hover:bg-[#322f33]"
                >
                  <span
                    className="h-2 w-2 shrink-0 rounded-full"
                    style={{ backgroundColor: colorForDomain(n.domain) }}
                  />
                  {n.label}
                </button>
              </li>
            ))}
          </ul>
        )}

        <div className="mt-8 border-t border-[#423e42] pt-5">
          <div className="mb-2 flex items-center justify-between">
            <p className="text-xs font-medium text-[#8F8978]">Personal writing patterns</p>
            <button
              onClick={analyzePatterns}
              disabled={!llmConfigured || patternsLoading}
              title={llmConfigured ? undefined : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"}
              className="text-xs text-accent-400 hover:text-accent-300 disabled:cursor-not-allowed disabled:opacity-40"
            >
              {patternsLoading ? "Analyzing…" : "Analyze my patterns"}
            </button>
          </div>
          <p className="mb-3 text-xs text-[#696A61]">
            Looks across your past Explain answers for habits you repeat — hedging, roundabout phrasing,
            passive voice — and suggests a more direct way to say the same thing.
          </p>

          {patternsError && <p className="text-xs text-amber-400">{patternsError}</p>}

          {patterns && patterns.length === 0 && (
            <p className="text-xs text-[#696A61]">No recurring pattern found yet — your phrasing looks consistent.</p>
          )}

          {patterns && patterns.length > 0 && (
            <ul className="space-y-3">
              {patterns.map((p, i) => (
                <li key={i} className="rounded-md border border-[#423e42] bg-[#201f21] p-3">
                  <p className="mb-1.5 text-xs font-semibold text-[#D4C6A6]">{p.name}</p>
                  <p className="text-xs text-[#696A61]">
                    <span className="text-amber-400">You wrote:</span> &ldquo;{p.example}&rdquo;
                  </p>
                  <p className="mt-1 text-xs text-[#8F8978]">
                    <span className="text-emerald-400">Try instead:</span> &ldquo;{p.betterVersion}&rdquo;
                  </p>
                  <p className="mt-1 text-[11px] italic text-[#696A61]">{p.why}</p>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    );
  }

  const color = colorForDomain(selected.domain);

  return (
    <div className="mx-auto flex h-full max-w-2xl flex-col px-6 py-8">
      <button onClick={() => setSelected(null)} className="mb-4 shrink-0 text-xs text-[#696A61] hover:text-[#8F8978]">
        ← Choose a different notion
      </button>

      <div className="mb-4 flex shrink-0 items-center gap-2">
        <span className="rounded-full px-2 py-0.5 text-xs font-medium text-white" style={{ backgroundColor: color }}>
          {selected.domain}
        </span>
        <h2 className="text-lg font-semibold text-[#D4C6A6]">{selected.label}</h2>
      </div>

      {selected.workQuestions && selected.workQuestions.length > 0 && (
        <div className="mb-5 shrink-0">
          <button
            onClick={() => setShowWorkQuestions((v) => !v)}
            className="text-xs text-[#696A61] hover:text-[#8F8978]"
          >
            {showWorkQuestions ? "▾" : "▸"} Asked on the job
          </button>
          {showWorkQuestions && (
            <ul className="mt-2 space-y-1.5 rounded-md border border-[#423e42] bg-[#201f21] p-3">
              {selected.workQuestions.map((wq, i) => (
                <li key={i} className="text-sm text-[#8F8978]">
                  &ldquo;{wq.question}&rdquo;
                </li>
              ))}
            </ul>
          )}
        </div>
      )}

      <div className="mb-5 flex shrink-0 gap-2">
        {EXPLAIN_LEVELS.map((lvl) => (
          <button
            key={lvl}
            onClick={() => changeLevel(lvl)}
            className={
              level === lvl
                ? "rounded-md border border-accent-400/40 bg-accent-300 px-3 py-1.5 text-xs font-medium text-[#1c140d]"
                : "rounded-md border border-[#423e42] bg-[#201f21] px-3 py-1.5 text-xs text-[#8F8978] hover:bg-[#322f33]"
            }
          >
            {passedLevels.has(lvl) && "✓ "}
            {EXPLAIN_LEVEL_LABELS[lvl]}
          </button>
        ))}
      </div>

      {setup && (
        <>
          <p className="mb-3 shrink-0 text-sm leading-relaxed text-[#8F8978]">{setup.prompt}</p>

          {setup.requiredKeywords.length > 0 && (
            <div className="mb-4 flex shrink-0 flex-wrap gap-1.5">
              {setup.requiredKeywords.map((kw) => (
                <span
                  key={kw}
                  className="rounded border border-[#423e42] bg-[#28262a] px-2 py-0.5 text-xs text-[#8F8978]"
                >
                  {kw}
                </span>
              ))}
            </div>
          )}

          {history.length > 0 && (
            <div className="mb-4 max-h-[40vh] space-y-3 overflow-y-auto rounded-md border border-[#423e42] bg-black/20 p-3">
              {history.map((attempt, i) => (
                <div key={i} className="space-y-1.5">
                  <div className="flex justify-end">
                    <p className="max-w-[85%] rounded-lg bg-accent-500/20 px-3 py-1.5 text-sm text-accent-100">
                      {attempt.answerText}
                    </p>
                  </div>
                  <div className="flex justify-start">
                    <div
                      className={
                        attempt.verdict === "pass"
                          ? "max-w-[85%] rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2"
                          : "max-w-[85%] rounded-lg border border-amber-500/30 bg-amber-500/10 px-3 py-2"
                      }
                    >
                      <p
                        className={
                          attempt.verdict === "pass"
                            ? "mb-1 text-[10px] font-semibold uppercase tracking-wide text-emerald-400"
                            : "mb-1 text-[10px] font-semibold uppercase tracking-wide text-amber-400"
                        }
                      >
                        {attempt.verdict === "pass" ? "Pass" : "Keep refining"}
                      </p>
                      <p className="text-sm leading-relaxed text-[#8F8978]">{attempt.feedback}</p>
                      {attempt.coveredKeywords.length > 0 && (
                        <p className="mt-1.5 text-xs text-[#696A61]">
                          <span className="text-emerald-400">Covered:</span>{" "}
                          {attempt.coveredKeywords.join(", ")}
                        </p>
                      )}
                      {attempt.missingKeywords.length > 0 && (
                        <p className="text-xs text-[#696A61]">
                          <span className="text-amber-400">Missing:</span>{" "}
                          {attempt.missingKeywords.join(", ")}
                        </p>
                      )}
                      {attempt.exampleAnswer && (
                        <div className="mt-2 border-t border-[#423e42] pt-2">
                          <p className="text-[10px] uppercase tracking-wide text-[#696A61]">Example explanation</p>
                          <p className="mt-0.5 text-sm leading-relaxed text-[#8F8978]">{attempt.exampleAnswer}</p>
                        </div>
                      )}
                      {attempt.correctedText && attempt.correctedText !== attempt.answerText && (
                        <div className="mt-2 border-t border-[#423e42] pt-2">
                          <p className="text-[10px] uppercase tracking-wide text-[#696A61]">Native phrasing</p>
                          <p className="mt-0.5 text-sm italic leading-relaxed text-[#8F8978]">
                            {attempt.correctedText}
                          </p>
                          <button
                            onClick={() => practicePronunciation(attempt)}
                            disabled={generatingPronunciation[attempt.id ?? attempt.answerText]}
                            className="mt-1.5 text-xs text-accent-400 hover:text-accent-300 disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            {generatingPronunciation[attempt.id ?? attempt.answerText]
                              ? "Preparing…"
                              : "Practice saying this →"}
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}

          <div className="mt-auto shrink-0">
            <textarea
              value={answer}
              onChange={(e) => setAnswer(e.target.value)}
              rows={4}
              placeholder={history.length > 0 ? "Refine your explanation…" : "Write your explanation here…"}
              className="w-full resize-none rounded-md border border-[#423e42] bg-[#28262a] p-3 text-sm text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
            />
            <label className="mt-2 block text-xs text-[#8F8978]"><input type="checkbox" checked={unaided} onChange={e => setUnaided(e.target.checked)} className="mr-2"/>I reconstructed the explanation without notes or hints</label>

            <button
              onClick={submit}
              disabled={!llmConfigured || submitting || answer.trim().length < 10}
              title={llmConfigured ? undefined : "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"}
              className="mt-3 rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2 text-sm text-[#D4C6A6] hover:bg-[#1d2829] disabled:cursor-not-allowed disabled:opacity-40"
            >
              {submitting ? "Grading…" : history.length > 0 ? "Submit again" : "Submit for feedback"}
            </button>

            {submitError && <p className="mt-2 text-xs text-red-400">{submitError}</p>}
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import { useContext, useState } from "react";
import { useReview } from "@/lib/useReview";
import ReviewIntervals from "@/components/ReviewIntervals";
import { StudySessionContext, useStudyQueue } from "@/lib/useStudySession";
import { useCourseFetch } from '@/lib/useCourseFetch';
import { colorForDomain } from "@/lib/types";
import type { Grade } from "@/lib/srs";
import { notifyXpUpdated } from "@/lib/xpEvent";
import { useCardShortcuts } from "@/lib/useCardShortcuts";
import type { DueCard } from "@/components/StudyClient";

interface DrillTabProps {
  initialCards: DueCard[];
}

const GRADE_OPTIONS: Array<{ grade: Grade; label: string; hint: string; className: string }> = [
  { grade: "again", label: "Again", hint: "didn't know it", className: "bg-red-500/20 border-red-500/40 text-red-200 hover:bg-red-500/30" },
  { grade: "hard", label: "Hard", hint: "struggled", className: "bg-amber-500/20 border-amber-500/40 text-amber-200 hover:bg-amber-500/30" },
  { grade: "good", label: "Good", hint: "got it", className: "bg-emerald-500/20 border-emerald-500/40 text-emerald-200 hover:bg-emerald-500/30" },
  { grade: "easy", label: "Easy", hint: "trivial", className: "bg-accent-500/20 border-accent-500/40 text-accent-200 hover:bg-accent-500/30" },
];

export default function DrillTab({ initialCards }: DrillTabProps) {
  const {courseId} = useContext(StudySessionContext);
  const fetch = useCourseFetch(courseId);
  const { cards, setCards, index, setIndex, revealed, setRevealed, sessionDone, setSessionDone, reviewedCount, setReviewedCount } = useStudyQueue("drill", initialCards);
  const saveReview=useReview("drill");
  const [grading, setGrading] = useState(false);
  const [gradeError, setGradeError] = useState<string | null>(null);

  const current = cards[index];

  const grade = async (g: Grade) => {
    if (!current || grading) return;
    setGrading(true);
    setGradeError(null);
    try {
      const res = await saveReview("notion", current.cardId ?? current.notion.id, g);
      if (!res.ok) throw new Error("Your review could not be saved. Please try again.");
      notifyXpUpdated();
      setReviewedCount((n) => n + 1);
      if (index + 1 >= cards.length) {
        setSessionDone(true);
      } else {
        setIndex((i) => i + 1);
        setRevealed(false);
      }
    } catch (error) {
      setGradeError(error instanceof Error ? error.message : "Your review could not be saved. Please try again.");
    } finally {
      setGrading(false);
    }
  };

  const restart = async () => {
    const res = await fetch("/api/review/queue");
    if (res.ok) {
      const data = await res.json();
      setCards(data.cards);
      setIndex(0);
      setRevealed(false);
      setReviewedCount(0);
      setSessionDone(data.cards.length === 0);
    }
  };

  useCardShortcuts({
    revealed,
    onReveal: () => setRevealed(true),
    onGrade: grade,
    disabled: grading || sessionDone || !current,
  });

  if (sessionDone) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-4 text-center">
        <p className="text-lg text-[#D4C6A6]">
          {reviewedCount > 0
            ? `Session done — ${reviewedCount} card${reviewedCount > 1 ? "s" : ""} reviewed.`
            : "Nothing due right now."}
        </p>
        <p className="max-w-sm text-sm text-[#696A61]">
          Cards come back on a schedule based on how well you know them — check back later, or
          generate more notions to grow the deck.
        </p>
        <button
          onClick={restart}
          className="rounded-md border border-[#423e42] bg-[#28262a] px-4 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33]"
        >
          Check again
        </button>
      </div>
    );
  }

  const color = colorForDomain(current.notion.domain);

  return (
    <div className="mx-auto flex h-full max-w-2xl flex-col justify-center gap-6 px-6 py-10">
      {gradeError && <p role="alert" className="text-sm text-red-400">{gradeError}</p>}
      {revealed && <ReviewIntervals type="notion" id={current.cardId ?? current.notion.id}/>}
      <div className="flex items-center justify-between text-xs text-[#696A61]">
        <span>
          Card {index + 1} / {cards.length}
        </span>
        {current.isNew && <span className="text-accent-400">new</span>}
      </div>

      <div className="rounded-lg border border-[#423e42] bg-[#201f21] p-6">
        <div className="mb-4 flex items-center gap-2">
          <span
            className="rounded-full px-2 py-0.5 text-xs font-medium text-white"
            style={{ backgroundColor: color }}
          >
            {current.notion.domain}
          </span>
          <h2 className="text-base font-semibold text-[#D4C6A6]">{current.notion.label}</h2>
        </div>

        {!revealed ? (
          <p className="text-sm italic text-[#696A61]">{current.question ?? "Recall the definition, then reveal."}</p>
        ) : (
          <div className="space-y-3">
            <p className="text-sm leading-relaxed text-[#D4C6A6]">{current.card.definition}</p>
            {current.card.example && (
              <p className="text-sm leading-relaxed text-[#8F8978]">
                <span className="font-medium text-[#696A61]">Example: </span>
                {current.card.example}
              </p>
            )}
            {current.notion.workQuestions && current.notion.workQuestions.length > 0 && (
              <p className="border-t border-[#423e42] pt-3 text-sm leading-relaxed text-[#8F8978]">
                <span className="font-medium text-accent-400">Could you answer: </span>
                {current.notion.workQuestions[0].question}
              </p>
            )}
          </div>
        )}
      </div>

      {!revealed ? (
        <button
          onClick={() => setRevealed(true)}
          className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829]"
        >
          Reveal <span className="text-[#696A61]">(space)</span>
        </button>
      ) : (
        <div className="grid grid-cols-4 gap-2">
          {GRADE_OPTIONS.map((opt, idx) => (
            <button
              key={opt.grade}
              onClick={() => grade(opt.grade)}
              disabled={grading}
              title={opt.hint}
              className={`rounded-md border px-3 py-2.5 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50 ${opt.className}`}
            >
              {opt.label} <span className="opacity-60">{idx + 1}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import type { Document, GenerationMode } from "@/lib/types";
import type {DocumentGenerationJob} from '@/lib/documentGeneration';

interface DocumentWithStats extends Document {
  passageCount: number;
  generatedPassageCount: number;
  generationJob?:DocumentGenerationJob;
}

interface DocumentsPanelProps {
  open: boolean;
  onClose: () => void;
  documents: DocumentWithStats[];
  llmConfigured: boolean;
  onUpload: (file: File, title: string) => Promise<void>;
  onGenerate: (documentId: string, enrichment?:boolean) => Promise<void>;
  mode:GenerationMode;
  onDelete: (documentId: string) => Promise<void>;
  generatingId: string | null;
  uploadError: string | null;
  generateError: string | null;
  generateInfo: string | null;
}

export default function DocumentsPanel({
  open,
  onClose,
  documents,
  llmConfigured,
  onUpload,
  onGenerate,
  mode,
  onDelete,
  generatingId,
  uploadError,
  generateError,
  generateInfo,
}: DocumentsPanelProps) {
  const [file, setFile] = useState<File | null>(null);
  const [title, setTitle] = useState("");
  const [uploading, setUploading] = useState(false);
  const [enrichment,setEnrichment]=useState(false);
  const [confirmingDeleteId, setConfirmingDeleteId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  if (!open) return null;

  const submit = async () => {
    if (!file || uploading) return;
    setUploading(true);
    try {
      await onUpload(file, title);
      setFile(null);
      setTitle("");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60" onClick={onClose}>
      <div
        className="flex max-h-[80vh] w-[560px] flex-col overflow-hidden rounded-lg border border-[#423e42] bg-[#201f21] shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between border-b border-[#423e42] px-5 py-3">
          <h2 className="font-display text-base font-medium tracking-wide text-accent-200">Documents</h2>
          <a href="/browse" className="text-xs text-accent-300">Sources, drafts & coverage</a>
          <button onClick={onClose} className="text-[#696A61] hover:text-[#8F8978]">
            ✕
          </button>
        </div>

        <div className="space-y-2 border-b border-[#423e42] p-5">
          <p className="text-xs text-[#696A61]">
            Upload a PDF (course, slides, book) — text is extracted per page and split into
            passages that ground strict-mode generation and chat.
          </p>
          <input
            type="file"
            accept="application/pdf"
            onChange={(e) => setFile(e.target.files?.[0] ?? null)}
            className="block w-full text-xs text-[#8F8978] file:mr-3 file:rounded file:border-0 file:bg-white/[0.08] file:px-3 file:py-1.5 file:text-xs file:text-[#D4C6A6] hover:file:bg-white/[0.14]"
          />
          <div className="flex gap-2">
            <input
              value={title}
              onChange={(e) => setTitle(e.target.value)}
              placeholder="Title (optional — defaults to filename)"
              className="flex-1 rounded-md border border-[#423e42] bg-[#28262a] px-2.5 py-1.5 text-xs text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
            />
            <button
              onClick={submit}
              disabled={!file || uploading}
              className="rounded-md border border-[#423e42] bg-[#322f33] px-3 text-xs text-[#D4C6A6] hover:bg-[#1d2829] disabled:cursor-not-allowed disabled:opacity-40"
            >
              {uploading ? "Uploading…" : "Upload"}
            </button>
          </div>
          {uploadError && <p className="text-xs text-red-400">{uploadError}</p>}
        </div>

        <div className="flex-1 overflow-y-auto p-5">
          <label className="mb-4 block text-xs text-[#8F8978]"><input type="checkbox" disabled={mode!=="open"} checked={enrichment && mode==="open"} onChange={e=>setEnrichment(e.target.checked)}/> Optional background knowledge, shown separately from course content (Open mode)</label>
          {documents.length === 0 ? (
            <p className="text-xs text-[#696A61]">No documents uploaded yet.</p>
          ) : (
            <ul className="space-y-3">
              {documents.map((doc) => {
                const remaining = doc.passageCount - doc.generatedPassageCount;
                const fullyGenerated = doc.passageCount > 0 && remaining <= 0;
                return (
                  <li
                    key={doc.id}
                    className="rounded-md border border-[#423e42] bg-[#201f21] p-3"
                  >
                    <div className="flex items-center justify-between gap-2">
                      <div className="min-w-0">
                        <p className="truncate text-sm text-[#D4C6A6]">{doc.title}</p>
                        <p className="text-xs text-[#696A61]">
                          {doc.pageCount ?? "?"} pages · {doc.generatedPassageCount}/{doc.passageCount}{" "}
                          passages processed
                          {fullyGenerated && " · done"}
                        </p>
                      </div>
                      <div className="flex shrink-0 items-center gap-1.5">
                        <button
                          onClick={() => onGenerate(doc.id,enrichment && mode==="open")}
                          disabled={!llmConfigured || generatingId === doc.id || fullyGenerated}
                          title={
                            !llmConfigured
                              ? "Set OPENAI_API_KEY, ANTHROPIC_API_KEY, or OLLAMA_MODEL to enable"
                              : fullyGenerated
                                ? "All passages already processed"
                                : undefined
                          }
                          className="rounded-md border border-[#423e42] bg-[#28262a] px-2.5 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33] disabled:cursor-not-allowed disabled:opacity-40"
                        >
                          {generatingId === doc.id
                            ? "Generating…"
                            : fullyGenerated
                              ? "Done"
                              : doc.generationJob?.status==='needs_review' || doc.generationJob?.status==='failed'
                                ? "Retry incomplete pages"
                              : doc.generatedPassageCount > 0
                                ? "Resume generation"
                                : "Generate notions"}
                        </button>
                        <button
                          onClick={() => setConfirmingDeleteId(doc.id)}
                          title="Remove this source document"
                          className="rounded px-1.5 py-1.5 text-xs text-[#696A61] hover:bg-red-500/10 hover:text-red-400"
                        >
                          ✕
                        </button>
                      </div>
                    </div>

                    {confirmingDeleteId === doc.id && (
                      <div className="mt-2 rounded border border-red-500/30 bg-red-500/10 p-2 text-xs text-red-300">
                        <p className="mb-1.5">
                          Remove &quot;{doc.title}&quot;? Its extracted passages are deleted and any
                          notion citing it loses that source (the notion itself stays).
                        </p>
                        <div className="flex gap-2">
                          <button
                            onClick={async () => {
                              setDeletingId(doc.id);
                              try {
                                await onDelete(doc.id);
                              } finally {
                                setDeletingId(null);
                                setConfirmingDeleteId(null);
                              }
                            }}
                            disabled={deletingId === doc.id}
                            className="rounded border border-red-500/40 bg-red-500/20 px-2 py-1 text-red-200 hover:bg-red-500/30 disabled:cursor-not-allowed disabled:opacity-50"
                          >
                            {deletingId === doc.id ? "Removing…" : "Remove"}
                          </button>
                          <button
                            onClick={() => setConfirmingDeleteId(null)}
                            className="rounded border border-[#423e42] px-2 py-1 text-[#8F8978] hover:bg-[#322f33]"
                          >
                            Cancel
                          </button>
                        </div>
                      </div>
                    )}
                  </li>
                );
              })}
            </ul>
          )}
          {generateInfo && <p className="mt-3 text-xs text-accent-300">{generateInfo}</p>}
          {generateError && <p className="mt-3 text-xs text-red-400">{generateError}</p>}
        </div>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import XpBar from "@/components/XpBar";

interface Course {
  id: string;
  name: string;
  createdAt: string;
}

// A slim bar across the very top of the app, like Claude.ai's conversation
// list — lets you switch between fully independent courses (each with its
// own documents/notions/decks) or start a brand new, empty one. Mounted
// once in the root layout so it's present on every page.
export default function CourseBar() {
  const [courses, setCourses] = useState<Course[]>([]);
  const [activeCourseId, setActiveCourseId] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState("");
  const [busy, setBusy] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingValue, setEditingValue] = useState("");

  useEffect(() => {
    fetch("/api/courses")
      .then((r) => r.json())
      .then((data) => {
        setCourses(data.courses);
        setActiveCourseId(data.activeCourseId);
      });
  }, []);

  const switchTo = async (id: string) => {
    if (id === activeCourseId || busy) return;
    setBusy(true);
    try {
      const res = await fetch(`/api/courses/${id}/activate`, { method: "POST" });
      // A full reload, deliberately: switching courses repoints the server's
      // active DB connection, so every server-fetched page needs a fresh
      // request, not a soft client-side navigation that could reuse cached data.
      // eslint-disable-next-line @next/next/no-location-assign-relative-destination
      if (res.ok) window.location.href = "/";
    } finally {
      setBusy(false);
    }
  };

  const createCourse = async () => {
    const name = newName.trim();
    if (name.length < 1 || busy) return;
    setBusy(true);
    try {
      const res = await fetch("/api/courses", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name }),
      });
      // eslint-disable-next-line @next/next/no-location-assign-relative-destination -- same reason as switchTo above: forces a fresh server fetch against the new course's empty DB
      if (res.ok) window.location.href = "/";
    } finally {
      setBusy(false);
    }
  };

  const startRenaming = (c: Course) => {
    setEditingId(c.id);
    setEditingValue(c.name);
  };

  const commitRename = async () => {
    const id = editingId;
    const name = editingValue.trim();
    setEditingId(null);
    if (!id || name.length < 1) return;
    const res = await fetch(`/api/courses/${id}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name }),
    });
    if (res.ok) {
      const data = await res.json();
      setCourses((prev) => prev.map((c) => (c.id === id ? data.course : c)));
    }
  };

  if (courses.length === 0) return null;

  return (
    <div className="flex items-center justify-between gap-1.5 border-b border-[#423e42] bg-[#201f21] px-3 py-1.5">
      <div className="flex items-center gap-1.5">
        {courses.map((c) =>
          editingId === c.id ? (
            <input
              key={c.id}
              autoFocus
              value={editingValue}
              onChange={(e) => setEditingValue(e.target.value)}
              onBlur={commitRename}
              onKeyDown={(e) => {
                if (e.key === "Enter") commitRename();
                if (e.key === "Escape") setEditingId(null);
              }}
              className="w-32 rounded border border-accent-400/60 bg-[#28262a] px-2 py-0.5 text-xs text-[#D4C6A6] focus:outline-none"
            />
          ) : (
            <button
              key={c.id}
              onClick={() => switchTo(c.id)}
              onDoubleClick={() => startRenaming(c)}
              title="Double-click to rename"
              className={
                c.id === activeCourseId
                  ? "rounded px-2.5 py-1 text-xs font-medium text-[#1c140d] bg-accent-300"
                  : "rounded px-2.5 py-1 text-xs text-[#696A61] hover:bg-[#322f33] hover:text-[#8F8978]"
              }
            >
              {c.name}
            </button>
          )
        )}

        {creating ? (
          <span className="flex items-center gap-1.5">
            <input
              autoFocus
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") createCourse();
                if (e.key === "Escape") setCreating(false);
              }}
              placeholder="Course name…"
              className="w-36 rounded border border-[#423e42] bg-[#28262a] px-2 py-0.5 text-xs text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
            />
            <button
              onClick={createCourse}
              disabled={busy || newName.trim().length < 1}
              className="rounded px-2.5 py-1 text-xs font-medium text-[#1c140d] bg-accent-400 hover:bg-accent-300 disabled:cursor-not-allowed disabled:opacity-40"
            >
              Create
            </button>
          </span>
        ) : (
          <button onClick={() => setCreating(true)} className="rounded px-2 py-1 text-xs text-[#696A61] hover:text-[#8F8978]">
            + New course
          </button>
        )}
      </div>

      <XpBar />
    </div>
  );
}

"use client";

import { useState } from "react";
import { useReview } from "@/lib/useReview";
import ReviewIntervals from "@/components/ReviewIntervals";
import { useStudyQueue } from "@/lib/useStudySession";
import { colorForDomain } from "@/lib/types";
import type { Grade } from "@/lib/srs";
import { notifyXpUpdated } from "@/lib/xpEvent";
import { useCardShortcuts } from "@/lib/useCardShortcuts";
import type { DueLink } from "@/components/StudyClient";

interface ConnectTabProps {
  initialCards: DueLink[];
}

const GRADE_OPTIONS: Array<{ grade: Grade; label: string; hint: string; className: string }> = [
  { grade: "again", label: "Again", hint: "didn't know it", className: "bg-red-500/20 border-red-500/40 text-red-200 hover:bg-red-500/30" },
  { grade: "hard", label: "Hard", hint: "struggled", className: "bg-amber-500/20 border-amber-500/40 text-amber-200 hover:bg-amber-500/30" },
  { grade: "good", label: "Good", hint: "got it", className: "bg-emerald-500/20 border-emerald-500/40 text-emerald-200 hover:bg-emerald-500/30" },
  { grade: "easy", label: "Easy", hint: "trivial", className: "bg-accent-500/20 border-accent-500/40 text-accent-200 hover:bg-accent-500/30" },
];

export function NotionPill({ label, domain }: { label: string; domain: string }) {
  const color = colorForDomain(domain);
  return (
    <div
      className="min-w-0 max-w-[160px] shrink-0 rounded-full border bg-[#28262a] px-4 py-2.5 text-center text-[13px] font-medium text-[#D4C6A6]"
      style={{ borderColor: color, boxShadow: `0 0 14px -4px ${color}` }}
    >
      <span className="truncate">{label}</span>
    </div>
  );
}

export function Connector({ type, color }: { type: string; color: string }) {
  return (
    <div className="relative flex min-w-[80px] flex-1 items-center">
      <div className="h-[2px] flex-1" style={{ backgroundColor: color, opacity: 0.6 }} />
      <div
        className="h-0 w-0 shrink-0 border-y-[5px] border-l-[8px] border-y-transparent"
        style={{ borderLeftColor: color, opacity: 0.6 }}
      />
      <span
        className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 whitespace-nowrap rounded border border-[#423e42] bg-[#1a1a1b] px-1.5 py-0.5 text-[10px] uppercase tracking-wide text-[#696A61]"
      >
        {type.replace("-", " ")}
      </span>
    </div>
  );
}

export default function ConnectTab({ initialCards }: ConnectTabProps) {
  const { cards, setCards, index, setIndex, revealed, setRevealed, sessionDone, setSessionDone, reviewedCount, setReviewedCount } = useStudyQueue("connect", initialCards);
  const saveReview=useReview("connect");
  const [grading, setGrading] = useState(false);
  const [gradeError, setGradeError] = useState<string | null>(null);

  const current = cards[index];

  const grade = async (g: Grade) => {
    if (!current || grading) return;
    setGrading(true);
    setGradeError(null);
    try {
      const res = await saveReview("link", current.cardId ?? current.link.id, g);
      if (!res.ok) throw new Error("Your review could not be saved. Please try again.");
      notifyXpUpdated();
      setReviewedCount((n) => n + 1);
      if (index + 1 >= cards.length) {
        setSessionDone(true);
      } else {
        setIndex((i) => i + 1);
        setRevealed(false);
      }
    } catch (error) {
      setGradeError(error instanceof Error ? error.message : "Your review could not be saved. Please try again.");
    } finally {
      setGrading(false);
    }
  };

  const restart = async () => {
    const res = await fetch("/api/review/connect-queue");
    if (res.ok) {
      const data = await res.json();
      setCards(data.cards);
      setIndex(0);
      setRevealed(false);
      setReviewedCount(0);
      setSessionDone(data.cards.length === 0);
    }
  };

  useCardShortcuts({
    revealed,
    onReveal: () => setRevealed(true),
    onGrade: grade,
    disabled: grading || sessionDone || !current,
  });

  if (sessionDone) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-4 text-center">
        <p className="text-lg text-[#D4C6A6]">
          {reviewedCount > 0
            ? `Session done — ${reviewedCount} connection${reviewedCount > 1 ? "s" : ""} reviewed.`
            : "No connections due right now."}
        </p>
        <p className="max-w-sm text-sm text-[#696A61]">
          Same spaced-repetition schedule as Drill, applied to how notions relate to each other
          instead of the notions themselves.
        </p>
        <button
          onClick={restart}
          className="rounded-md border border-[#423e42] bg-[#28262a] px-4 py-2 text-sm text-[#D4C6A6] hover:bg-[#322f33]"
        >
          Check again
        </button>
      </div>
    );
  }

  const sourceColor = colorForDomain(current.source.domain);

  return (
    <div className="mx-auto flex h-full max-w-2xl flex-col justify-center gap-6 px-6 py-10">
      {gradeError && <p role="alert" className="text-sm text-red-400">{gradeError}</p>}
      {revealed && <ReviewIntervals type="link" id={current.cardId ?? current.link.id}/>}
      <div className="flex items-center justify-between text-xs text-[#696A61]">
        <span>
          Connection {index + 1} / {cards.length}
        </span>
        {current.isNew && <span className="text-accent-400">new</span>}
      </div>

      <div className="rounded-lg border border-[#423e42] bg-[#201f21] p-6">
        <div className="mb-6 flex items-center gap-2">
          <NotionPill label={current.source.label} domain={current.source.domain} />
          <Connector type={current.link.type} color={sourceColor} />
          <NotionPill label={current.target.label} domain={current.target.domain} />
        </div>

        <p className="text-center text-xs uppercase tracking-wide text-[#696A61] mb-3">
          {current.question ?? "How are these connected?"}
        </p>

        {revealed ? (
          <p className="rounded-md bg-accent-500/10 p-3 text-sm leading-relaxed text-[#8F8978]">
            {current.link.description}
          </p>
        ) : (
          <div className="rounded-md border border-dashed border-white/10 bg-[#201f21] p-3 text-center text-sm text-[#696A61]">
            •••
          </div>
        )}
      </div>

      {!revealed ? (
        <button
          onClick={() => setRevealed(true)}
          className="rounded-md border border-[#423e42] bg-[#322f33] px-4 py-2.5 text-sm text-[#D4C6A6] hover:bg-[#1d2829]"
        >
          Reveal <span className="text-[#696A61]">(space)</span>
        </button>
      ) : (
        <div className="grid grid-cols-4 gap-2">
          {GRADE_OPTIONS.map((opt, idx) => (
            <button
              key={opt.grade}
              onClick={() => grade(opt.grade)}
              disabled={grading}
              title={opt.hint}
              className={`rounded-md border px-3 py-2.5 text-sm font-medium disabled:cursor-not-allowed disabled:opacity-50 ${opt.className}`}
            >
              {opt.label} <span className="opacity-60">{idx + 1}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";
import { useState } from 'react';
import type { ClairLesson } from '@/lib/clair';

const STEPS = ['Context', 'Logic', 'Connections', 'Implications', 'Reconstruction'] as const;
export default function ClairReader({lesson, onSelect}: {lesson: ClairLesson; onSelect?: (id: string) => void}) {
  const [step, setStep] = useState(0);
  const [revealed, setRevealed] = useState(false);
  const move = (index: number) => {setStep(index); setRevealed(false);};
  return <div className="space-y-3 text-sm leading-relaxed text-[#8F8978]" data-testid="clair-reader">
    <nav aria-label="C.L.A.I.R. dimensions" className="flex flex-wrap gap-2 text-xs">
      {STEPS.map((label, index) => <button key={label} aria-current={step === index ? 'step' : undefined} onClick={() => move(index)} className={step === index ? 'text-accent-400' : 'text-[#696A61] hover:text-[#8F8978]'}>{label}</button>)}
    </nav>
    {step === 0 && <p className="whitespace-pre-line">{lesson.context}</p>}
    {step === 1 && <>
      <p>{lesson.logic.answer}</p>
      <ol className="list-decimal space-y-2 pl-5">{lesson.logic.steps.map((text, index) => <li key={index}>{text}</li>)}</ol>
      {lesson.logic.analogy.model && <p><span className="text-[#696A61]">Teaching analogy: </span>{lesson.logic.analogy.model} {lesson.logic.analogy.mapping} Limit: {lesson.logic.analogy.limit}</p>}
      <details><summary className="cursor-pointer text-accent-400">Precise formulation and conditions</summary><p className="mt-2 whitespace-pre-line">{lesson.logic.formalism}</p></details>
    </>}
    {step === 2 && (lesson.articulations.length ? <ul className="space-y-3">{lesson.articulations.map((connection, index) => <li key={`${connection.notionId}:${index}`}>
      {onSelect ? <button className="text-accent-400" onClick={() => onSelect(connection.notionId)}>{connection.label}</button> : <span className="text-accent-400">{connection.label}</span>}
      <span className="ml-2 text-xs text-[#696A61]">{connection.type === 'prerequisite' ? connection.direction === 'incoming' ? 'Prerequisite for this idea' : 'Builds on this idea' : connection.type}</span>
      <p>{connection.explanation}</p>
    </li>)}</ul> : <p>No source-supported relationship has been established for this concept yet.</p>)}
    {step === 3 && <>
      <p className="text-xs text-[#696A61]">{lesson.implications.origin === 'source' ? 'Situation quoted from the course' : 'Generated practice situation · not attributed to the lecturer'}</p>
      <p>{lesson.implications.setup}</p><p><span className="text-[#696A61]">Assume: </span>{lesson.implications.assumptions}</p>
      <p className="text-[#D4C6A6]">{lesson.implications.question}</p>
      {!revealed ? <button onClick={() => setRevealed(true)} className="text-accent-400">Compare your reasoning</button> : <p>{lesson.implications.answer} {lesson.implications.why}</p>}
      {lesson.implications.limits && <p>Limit: {lesson.implications.limits}</p>}
    </>}
    {step === 4 && <>
      <p className="text-[#D4C6A6]">{lesson.reconstruction.question}</p>
      <p className="text-xs text-[#696A61]">Explain it aloud or in your own words before revealing the reasoning. Reading a lesson does not change mastery.</p>
      {!revealed ? <button onClick={() => setRevealed(true)} className="text-accent-400">Show the reasoning to reconstruct</button> : <p className="whitespace-pre-line">{lesson.reconstruction.expectedAnswer}</p>}
      <a href="/interview" className="block text-xs text-accent-400">Test your understanding in Interview →</a>
    </>}
    <div className="flex justify-between border-t border-[#423e42] pt-2 text-xs">
      <button disabled={step === 0} onClick={() => move(step - 1)} className="disabled:opacity-30">← Previous</button>
      <span>C.L.A.I.R. · {step + 1} / 5</span>
      <button disabled={step === 4} onClick={() => move(step + 1)} className="disabled:opacity-30">Next →</button>
    </div>
    <details className="text-xs"><summary className="cursor-pointer text-[#696A61]">Course sources · analogies and hypothetical examples are teaching aids</summary>
      {lesson.sources.map((source, index) => <div key={index} className="mt-2"><a className="text-accent-400" href={`/api/documents/${encodeURIComponent(source.documentId)}/file#page=${source.page}`} target="_blank" rel="noreferrer">Slide {source.page} ↗</a><p className="mt-1">{source.quote || source.visualDescription}</p></div>)}
    </details>
  </div>;
}

"use client";

import { useState } from "react";
import type { ChatTurn } from "@/lib/llm";

interface ChatPanelProps {
  messages: ChatTurn[];
  loading: boolean;
  disabled: boolean;
  disabledReason?: string;
  onSend: (text: string) => void;
}

export default function ChatPanel({ messages, loading, disabled, disabledReason, onSend }: ChatPanelProps) {
  const [draft, setDraft] = useState("");

  const submit = () => {
    const text = draft.trim();
    if (!text || loading || disabled) return;
    onSend(text);
    setDraft("");
  };

  return (
    <div className="flex flex-col gap-2">
      <h3 className="text-xs font-semibold uppercase tracking-wide text-[#696A61]">
        Ask about this notion
      </h3>

      {messages.length > 0 && (
        <div className="max-h-56 space-y-2 overflow-y-auto rounded-md border border-[#423e42] bg-black/20 p-2.5">
          {messages.map((m, i) => (
            <div
              key={i}
              className={m.role === "user" ? "text-right" : "text-left"}
            >
              <span
                className={
                  m.role === "user"
                    ? "inline-block rounded-lg bg-accent-500/20 px-2.5 py-1.5 text-xs text-accent-200"
                    : "inline-block rounded-lg bg-[#322f33] px-2.5 py-1.5 text-xs text-[#8F8978]"
                }
              >
                {m.content}
              </span>
            </div>
          ))}
          {loading && <p className="text-left text-xs text-[#696A61]">Thinking…</p>}
        </div>
      )}

      <div className="flex gap-1.5">
        <input
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") submit();
          }}
          disabled={disabled}
          placeholder={disabled ? (disabledReason ?? "Unavailable") : "Ask a question…"}
          className="flex-1 rounded-md border border-[#423e42] bg-[#28262a] px-2.5 py-1.5 text-xs text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none disabled:cursor-not-allowed disabled:opacity-50"
        />
        <button
          onClick={submit}
          disabled={disabled || loading || draft.trim().length === 0}
          className="rounded-md border border-[#423e42] bg-[#28262a] px-3 text-xs text-[#8F8978] hover:bg-[#322f33] disabled:cursor-not-allowed disabled:opacity-40"
        >
          Send
        </button>
      </div>
    </div>
  );
}

"use client";
import { useState } from "react";
import type { StudyCard } from "@/lib/contentQuality";
import { useCourseFetch } from "@/lib/useCourseFetch";
export default function CardEditor({card,courseId,onSave,onClose}:{card:StudyCard;courseId:string;onSave:(card:StudyCard)=>void;onClose:()=>void}) {
  const fetch=useCourseFetch(courseId);
  const [question,setQuestion]=useState(card.question), [answer,setAnswer]=useState(card.answer), [example,setExample]=useState(card.example);
  const [error,setError]=useState(""), [busy,setBusy]=useState(false);
  const save=async(status:StudyCard["status"])=>{
    setBusy(true);setError("");
    try {const res=await fetch(`/api/cards/${card.id}`,{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({question,answer,example,status})});const data=await res.json();if(!res.ok)throw new Error(data.error);onSave(data.card);}
    catch(e){setError(e instanceof Error?e.message:"Save failed");}finally{setBusy(false);}
  };
  return <div className="fixed inset-0 z-50 overflow-auto bg-black/70 p-6" role="dialog" aria-label="Edit card">
    <div className="mx-auto grid max-w-5xl gap-5 rounded-lg border border-[#423e42] bg-[#201f21] p-5 md:grid-cols-2">
      <div className="space-y-3"><button onClick={onClose}>Close</button><h2 className="text-lg">Verify and edit card</h2>
        <label className="block">Question<textarea className="mt-1 w-full rounded bg-[#28262a] p-2" value={question} onChange={e=>setQuestion(e.target.value)}/></label>
        <label className="block">Answer<textarea rows={6} className="mt-1 w-full rounded bg-[#28262a] p-2" value={answer} onChange={e=>setAnswer(e.target.value)}/></label>
        <label className="block">Example<textarea className="mt-1 w-full rounded bg-[#28262a] p-2" value={example} onChange={e=>setExample(e.target.value)}/></label>
        <p className="text-xs text-[#8F8978]">{card.kind} · {card.objective}</p>
        {card.warnings.map((w,i)=><p className="text-xs text-amber-300" key={i}>{w}</p>)}
        <div className="flex flex-wrap gap-3">{(["draft","ready","suspended"] as const).map(status=><button className="rounded border border-[#423e42] px-3 py-2" disabled={busy} key={status} onClick={()=>save(status)}>{status==="ready"?"Approve & save":status==="draft"?"Save draft":"Suspend"}</button>)}</div>
        {error && <p role="alert" className="text-red-400">{error}</p>}
      </div>
      <div className="space-y-3"><h3>Source evidence</h3>{!card.evidence.length && <p>No source evidence. Review this legacy card carefully.</p>}
        {card.evidence.map((e,i)=><div key={i}><a className="text-accent-300 underline" target="_blank" rel="noreferrer" href={`/api/documents/${e.documentId}/file#page=${e.page}`}>Slide {e.page}</a><blockquote className="my-2 border-l-2 border-accent-400 pl-3 text-sm">{e.quote || e.visualDescription || "Legacy page citation without a verified quotation"}</blockquote></div>)}
        {card.evidence[0] && <iframe title="Original slide" className="h-[500px] w-full rounded" src={`/api/documents/${card.evidence[0].documentId}/file#page=${card.evidence[0].page}`}/>}
      </div>
    </div>
  </div>;
}

"use client";

import { useEffect, useRef } from "react";

// A synthesized mechanical click on every button press — not a reproduction
// of any copyrighted game audio (that would require ripping an actual asset
// file), just a short two-part "knock + thunk" built from oscillators run
// through a lowpass filter for warmth, aiming for the same deep, thick,
// satisfying old-client feel (think the old League client's button sound)
// rather than a thin digital beep. Delegated to a single document-level
// listener so no individual button needs wiring.
export default function ButtonSound() {
  const ctxRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    const getContext = () => {
      if (!ctxRef.current) {
        const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
        ctxRef.current = new Ctor();
      }
      return ctxRef.current;
    };

    const schedule = (ctx: AudioContext) => {
      const now = ctx.currentTime;

      // A soft lowpass on everything is what keeps this feeling "thick" and
      // wooden instead of thin/digital — it rounds off the harmonics that
      // would otherwise read as a beep.
      const warmth = ctx.createBiquadFilter();
      warmth.type = "lowpass";
      warmth.frequency.setValueAtTime(750, now);
      warmth.Q.value = 0.7;
      warmth.connect(ctx.destination);

      // Brief low "knock" transient — the attack, not a high-pitched tick
      const knock = ctx.createOscillator();
      const knockGain = ctx.createGain();
      knock.type = "triangle";
      knock.frequency.setValueAtTime(260, now);
      knock.frequency.exponentialRampToValueAtTime(95, now + 0.035);
      knockGain.gain.setValueAtTime(0.22, now);
      knockGain.gain.exponentialRampToValueAtTime(0.0008, now + 0.045);
      knock.connect(knockGain).connect(warmth);
      knock.start(now);
      knock.stop(now + 0.05);

      // Deep, slightly delayed body — the "thunk" that gives it real weight
      const thunk = ctx.createOscillator();
      const thunkGain = ctx.createGain();
      thunk.type = "sine";
      thunk.detune.setValueAtTime(-5, now);
      thunk.frequency.setValueAtTime(130, now + 0.006);
      thunk.frequency.exponentialRampToValueAtTime(66, now + 0.15);
      thunkGain.gain.setValueAtTime(0.3, now + 0.008);
      thunkGain.gain.exponentialRampToValueAtTime(0.0008, now + 0.19);
      thunk.connect(thunkGain).connect(warmth);
      thunk.start(now + 0.006);
      thunk.stop(now + 0.2);

      // A sub-octave layer underneath, decaying slower than the main thunk —
      // two flat sine tones decaying in lockstep read as "flat"; staggering
      // a deeper layer under it is what gives the click a sense of depth.
      const sub = ctx.createOscillator();
      const subGain = ctx.createGain();
      sub.type = "sine";
      sub.detune.setValueAtTime(4, now);
      sub.frequency.setValueAtTime(62, now + 0.014);
      sub.frequency.exponentialRampToValueAtTime(36, now + 0.2);
      subGain.gain.setValueAtTime(0, now + 0.014);
      subGain.gain.linearRampToValueAtTime(0.2, now + 0.03);
      subGain.gain.exponentialRampToValueAtTime(0.0008, now + 0.26);
      sub.connect(subGain).connect(warmth);
      sub.start(now + 0.014);
      sub.stop(now + 0.27);
    };

    const playClick = () => {
      const ctx = getContext();
      // ctx.resume() is async and ctx.currentTime stays frozen while
      // suspended (Chrome auto-suspends an idle AudioContext after ~30s, so
      // this isn't just a first-click thing) — scheduling the oscillators
      // immediately against that frozen time meant their start/stop window
      // had often already elapsed by the time resume() actually completed,
      // so nothing audible came out. Only schedule once truly running.
      if (ctx.state === "suspended") {
        ctx.resume().then(() => schedule(ctx));
      } else {
        schedule(ctx);
      }
    };

    const onPointerDown = (e: MouseEvent) => {
      const target = e.target as HTMLElement | null;
      // Several nav items (Study/Progress/Browse/Interview, course-bar
      // pills) are Next.js <Link>s styled as buttons, not <button>
      // elements — without including `a` here they silently stayed silent.
      const control = target?.closest("button, a");
      if (!control) return;
      if (control instanceof HTMLButtonElement && control.disabled) return;
      playClick();
    };

    document.addEventListener("click", onPointerDown, true);
    return () => document.removeEventListener("click", onPointerDown, true);
  }, []);

  return null;
}

"use client";

import { useMemo, useState } from "react";
import CardEditor from "@/components/CardEditor";
import { useCourseFetch } from "@/lib/useCourseFetch";
import type { StudyCard } from "@/lib/contentQuality";
import QualityPanel from "@/components/QualityPanel";
import type { BrowseCard, CardType } from "@/lib/db";

interface BrowseClientProps {
  courseId:string;
  initialCards: BrowseCard[];
}

const MATURE_THRESHOLD_DAYS = 21;

const TYPE_LABELS: Record<CardType, string> = {
  notion: "Drill",
  link: "Connect",
  pronunciation: "Pronounce",
  vocabulary: "Vocab",
};

const TYPE_BADGE_CLASS: Record<CardType, string> = {
  notion: "bg-accent-500/15 text-accent-300",
  link: "bg-sky-500/15 text-sky-300",
  pronunciation: "bg-pink-500/15 text-pink-300",
  vocabulary: "bg-lime-500/15 text-lime-300",
};

function maturityOf(card: BrowseCard): "new" | "young" | "mature" {
  if (card.isNew) return "new";
  return card.intervalDays >= MATURE_THRESHOLD_DAYS ? "mature" : "young";
}

const MATURITY_BADGE_CLASS: Record<"new" | "young" | "mature", string> = {
  new: "bg-slate-500/15 text-slate-400",
  young: "bg-amber-500/15 text-amber-300",
  mature: "bg-emerald-500/15 text-emerald-300",
};

function formatDue(card: BrowseCard): string {
  if (card.isNew) return "new";
  if (!card.dueAt) return "—";
  const due = new Date(card.dueAt).getTime();
  const now = Date.now();
  const days = Math.round((due - now) / 86_400_000);
  if (days < 0) return `overdue ${Math.abs(days)}d`;
  if (days === 0) return "today";
  return `in ${days}d`;
}

export default function BrowseClient({ initialCards,courseId }: BrowseClientProps) {
  const fetch=useCourseFetch(courseId);
  const [editing,setEditing]=useState<StudyCard|null>(null);
  const [statusFilter,setStatusFilter]=useState("all");
  const [cards, setCards] = useState(initialCards);
  const [filter, setFilter] = useState<"all" | CardType>("all");
  const [query, setQuery] = useState("");
  const [busyKey, setBusyKey] = useState<string | null>(null);

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return cards
      .filter((c) => filter === "all" || c.cardType === filter)
      .filter((c)=>statusFilter==="all" || c.studyCard?.status===statusFilter || (statusFilter==="legacy" && c.studyCard?.promptVersion==="legacy"))
      .filter((c) => !q || `${c.label} ${c.studyCard?.answer ?? ""}`.toLowerCase().includes(q))
      .slice()
      .sort((a, b) => {
        const aKey = a.isNew || !a.dueAt ? -Infinity : new Date(a.dueAt).getTime();
        const bKey = b.isNew || !b.dueAt ? -Infinity : new Date(b.dueAt).getTime();
        return aKey - bKey;
      });
  }, [cards, filter, query, statusFilter]);

  const counts = useMemo(() => {
    const result: Record<"all" | CardType, number> = {
      all: cards.length,
      notion: 0,
      link: 0,
      pronunciation: 0,
      vocabulary: 0,
    };
    for (const c of cards) result[c.cardType]++;
    return result;
  }, [cards]);

  const runAction = async (card: BrowseCard, action: "reset" | "due-now") => {
    const key = `${card.cardType}:${card.cardId}:${action}`;
    setBusyKey(key);
    try {
      const res = await fetch(`/api/review/${card.cardType}/${card.cardId}/${action}`, { method: "POST" });
      if (!res.ok) return;
      setCards((prev) =>
        prev.map((c) => {
          if (c.cardType !== card.cardType || c.cardId !== card.cardId) return c;
          if (action === "reset") return { ...c, isNew: true, intervalDays: 0, dueAt: null, repetitions: 0 };
          return { ...c, isNew: false, dueAt: new Date().toISOString() };
        })
      );
    } finally {
      setBusyKey(null);
    }
  };

  const deleteCard = async (card: BrowseCard) => {
    const noun = "card";
    if (!window.confirm(`Delete this ${noun} permanently? "${card.label}"`)) return;
    const key = `${card.cardType}:${card.cardId}:delete`;
    setBusyKey(key);
    try {
      const res = await fetch(`/api/review/${card.cardType}/${card.cardId}`, { method: "DELETE" });
      if (!res.ok) return;
      setCards((prev) => prev.filter((c) => !(c.cardType === card.cardType && c.cardId === card.cardId)));
    } finally {
      setBusyKey(null);
    }
  };

  return (
    <div className="mx-auto max-w-3xl px-6 py-8">
      <QualityPanel courseId={courseId}/>
      {editing && <CardEditor key={editing.id} courseId={courseId} card={editing} onClose={()=>setEditing(null)} onSave={updated=>{setCards(previous=>previous.map(c=>c.cardId===updated.id?{...c,label:updated.question,detail:updated.status,studyCard:updated}:c));setEditing(null);}}/>}
      <select className="mb-4 rounded bg-[#28262a] p-2" aria-label="Card status" value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}>{["all","ready","draft","suspended","legacy"].map(v=><option key={v} value={v}>{v}</option>)}</select>
      <div className="mb-5 flex flex-wrap items-center gap-2">
        {(["all", "notion", "link", "pronunciation", "vocabulary"] as const).map((t) => (
          <button
            key={t}
            onClick={() => setFilter(t)}
            className={
              filter === t
                ? "rounded-md border border-accent-400/40 bg-accent-300 px-3 py-1.5 text-xs font-medium text-[#1c140d]"
                : "rounded-md border border-[#423e42] bg-[#201f21] px-3 py-1.5 text-xs text-[#8F8978] hover:bg-[#322f33]"
            }
          >
            {t === "all" ? "All" : TYPE_LABELS[t]} ({counts[t]})
          </button>
        ))}
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search…"
          className="ml-auto w-48 rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] placeholder:text-[#696A61] focus:border-accent-400/60 focus:outline-none"
        />
      </div>

      {visible.length === 0 ? (
        <p className="py-10 text-center text-sm text-[#696A61]">No cards match.</p>
      ) : (
        <div className="divide-y divide-white/[0.06] rounded-lg border border-[#423e42] bg-[#201f21]">
          {visible.map((card) => {
            const maturity = maturityOf(card);
            return (
              <div key={`${card.cardType}:${card.cardId}`} className="flex items-center gap-3 px-4 py-3">
                <div className="min-w-0 flex-1">
                  <p className="text-sm text-[#D4C6A6]">{card.label}</p>
                  {card.studyCard && <p className="mt-1 line-clamp-2 text-xs text-[#8F8978]">{card.studyCard.answer}</p>}
                  <div className="mt-1 flex items-center gap-2">
                    <span className={`rounded px-1.5 py-0.5 text-[10px] font-medium ${TYPE_BADGE_CLASS[card.cardType]}`}>
                      {TYPE_LABELS[card.cardType]}
                    </span>
                    <span className={`rounded px-1.5 py-0.5 text-[10px] font-medium ${MATURITY_BADGE_CLASS[maturity]}`}>
                      {maturity}
                    </span>
                    <span className="text-[11px] text-[#696A61]">{card.detail}</span>
                  </div>
                </div>
                <div className="shrink-0 text-right text-xs text-[#696A61]">
                  <p>{formatDue(card)}</p>
                  {!card.isNew && <p className="text-[10px] text-[#696A61]">{card.repetitions} reviews</p>}
                </div>
                <div className="flex shrink-0 gap-1.5">
                  {card.studyCard && <button className="rounded border border-[#423e42] px-2 py-1 text-xs" onClick={()=>setEditing(card.studyCard!)}>Verify / edit</button>}
                  <button
                    onClick={() => runAction(card, "due-now")}
                    disabled={card.isNew || busyKey === `${card.cardType}:${card.cardId}:due-now`}
                    className="rounded border border-[#423e42] bg-[#28262a] px-2 py-1 text-[11px] text-[#8F8978] hover:bg-[#322f33] disabled:cursor-not-allowed disabled:opacity-30"
                  >
                    Review now
                  </button>
                  <button
                    onClick={() => runAction(card, "reset")}
                    disabled={card.isNew || busyKey === `${card.cardType}:${card.cardId}:reset`}
                    className="rounded border border-[#423e42] bg-[#28262a] px-2 py-1 text-[11px] text-[#8F8978] hover:bg-[#322f33] disabled:cursor-not-allowed disabled:opacity-30"
                  >
                    Reset
                  </button>
                  <button
                    onClick={() => deleteCard(card)}
                    disabled={busyKey === `${card.cardType}:${card.cardId}:delete`}
                    className="rounded border border-red-500/20 bg-red-500/[0.04] px-2 py-1 text-[11px] text-red-400 hover:bg-red-500/10 disabled:cursor-not-allowed disabled:opacity-30"
                  >
                    Delete
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

"use client";

import { useState } from "react";
import { useCourseFetch } from "@/lib/useCourseFetch";

interface BackupPanelProps {
  courseId:string;
  open: boolean;
  onClose: () => void;
}

export default function BackupPanel({ open, onClose,courseId }: BackupPanelProps) {
  const fetch=useCourseFetch(courseId);
  const [file, setFile] = useState<File | null>(null);
  const [confirming, setConfirming] = useState(false);
  const [importing, setImporting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [done, setDone] = useState<string | null>(null);
  const [confirmingReset, setConfirmingReset] = useState(false);
  const [resetting, setResetting] = useState(false);
  const [confirmingClearMapping, setConfirmingClearMapping] = useState(false);
  const [clearingMapping, setClearingMapping] = useState(false);
  const busy = importing || resetting || clearingMapping;

  if (!open) return null;

  const doImport = async () => {
    if (!file) return;
    setImporting(true);
    setError(null);
    try {
      const formData = new FormData();
      formData.append("file", file);
      const res = await fetch("/api/import", { method: "POST", body: formData });
      const data = await res.json();
      if (!res.ok) {
        setError(data.error ?? "Import failed.");
        return;
      }
      setDone(`Restored ${data.notions} notions, ${data.links} links, ${data.documents} documents.`);
      setTimeout(() => window.location.reload(), 1200);
    } catch {
      setError("Network error during import.");
    } finally {
      setImporting(false);
    }
  };

  const doReset = async () => {
    setResetting(true);
    try {
      const res = await fetch("/api/reset", { method: "POST" });
      if (res.ok) window.location.reload();
    } finally {
      setResetting(false);
    }
  };

  const doClearMapping = async () => {
    setClearingMapping(true);
    setError(null);
    try {
      const res = await fetch("/api/graph/clear", { method: "POST" });
      if (!res.ok) {
        const data = await res.json();
        throw new Error(data.error ?? "Could not clear the mapping.");
      }
      window.location.reload();
    } catch (error) {
      setError(error instanceof Error ? error.message : "Network error while clearing the mapping.");
    } finally {
      setClearingMapping(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60" onClick={onClose}>
      <div
        className="max-h-[90vh] w-[480px] overflow-y-auto rounded-lg border border-[#423e42] bg-[#201f21] shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between border-b border-[#423e42] px-5 py-3">
          <h2 className="font-display text-base font-medium tracking-wide text-accent-200">Backup</h2>
          <button onClick={onClose} className="text-[#696A61] hover:text-[#8F8978]">
            ✕
          </button>
        </div>

        <div className="space-y-5 p-5">
          <div>
            <h3 className="mb-1.5 text-xs font-semibold uppercase tracking-wide text-[#696A61]">Export</h3>
            <p className="mb-2.5 text-xs text-[#696A61]">
              Download everything — notions, links, documents and their extracted text, drill
              scheduling, original PDFs, card edits, quality audits, and explain history — as one JSON file.
            </p>
            <a
              href="/api/export"
              download
              className="inline-block rounded-md border border-[#423e42] bg-[#322f33] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#1d2829]"
            >
              Download backup (.json)
            </a>
          </div>

          <div className="border-t border-[#423e42] pt-5">
            <h3 className="mb-1.5 text-xs font-semibold uppercase tracking-wide text-[#696A61]">
              Restore
            </h3>
            <p className="mb-2.5 text-xs text-[#696A61]">
              Restoring a backup <span className="text-red-400">replaces everything currently here</span>{" "}
              — there&apos;s no undo. Export first if you want to keep what&apos;s here now.
            </p>
            <input
              type="file"
              accept="application/json"
              onChange={(e) => {
                setFile(e.target.files?.[0] ?? null);
                setConfirming(false);
                setDone(null);
                setError(null);
              }}
              className="mb-2.5 block w-full text-xs text-[#8F8978] file:mr-3 file:rounded file:border-0 file:bg-white/[0.08] file:px-3 file:py-1.5 file:text-xs file:text-[#D4C6A6] hover:file:bg-white/[0.14]"
            />

            {file && !confirming && !done && (
              <button
                onClick={() => setConfirming(true)}
                className="rounded-md border border-[#423e42] bg-[#28262a] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#322f33]"
              >
                Restore from this file…
              </button>
            )}

            {confirming && !done && (
              <div className="rounded-md border border-red-500/30 bg-red-500/10 p-3 text-xs text-red-300">
                <p className="mb-2">
                  This will permanently delete everything currently in this encyclopedia and
                  replace it with the contents of &quot;{file?.name}&quot;. Are you sure?
                </p>
                <div className="flex gap-2">
                  <button
                    onClick={doImport}
                    disabled={busy}
                    className="rounded border border-red-500/40 bg-red-500/20 px-2 py-1 text-red-200 hover:bg-red-500/30 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {importing ? "Restoring…" : "Yes, replace everything"}
                  </button>
                  <button
                    onClick={() => setConfirming(false)}
                    className="rounded border border-[#423e42] px-2 py-1 text-[#8F8978] hover:bg-[#322f33]"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}

            {done && <p className="text-xs text-emerald-400">{done} Reloading…</p>}
          </div>

          <div className="border-t border-[#423e42] pt-5">
            <h3 className="mb-1.5 text-xs font-semibold uppercase tracking-wide text-[#696A61]">Mapping only</h3>
            <p className="mb-2.5 text-xs text-[#696A61]">
              Clear the mapping for this course. All cards in Browse, review progress and documents are kept.
              You can generate a new mapping from your documents afterwards.
            </p>
            {!confirmingClearMapping ? (
              <button
                onClick={() => setConfirmingClearMapping(true)}
                disabled={busy}
                className="rounded-md border border-[#423e42] bg-[#322f33] px-3 py-1.5 text-xs text-[#D4C6A6] hover:bg-[#28262a] disabled:opacity-50"
              >
                Clear mapping only…
              </button>
            ) : (
              <div className="rounded-md border border-amber-500/30 bg-amber-500/10 p-3 text-xs text-amber-200">
                <p className="mb-2">Clear this course&apos;s mapping? Your Browse cards and their progress will be preserved.</p>
                <div className="flex gap-2">
                  <button onClick={doClearMapping} disabled={busy} className="border border-amber-500/40 bg-amber-500/20 px-2 py-1 hover:bg-amber-500/30 disabled:opacity-50">
                    {clearingMapping ? "Clearing…" : "Yes, clear mapping only"}
                  </button>
                  <button onClick={() => setConfirmingClearMapping(false)} disabled={busy} className="border border-[#423e42] px-2 py-1 text-[#8F8978] hover:bg-[#322f33]">
                    Cancel
                  </button>
                </div>
              </div>
            )}
          </div>

          <div className="border-t border-[#423e42] pt-5">
            <h3 className="mb-1.5 text-xs font-semibold uppercase tracking-wide text-[#696A61]">Reset</h3>
            <p className="mb-2.5 text-xs text-[#696A61]">
              Empties this course completely — every notion, link, document, and study deck.{" "}
              <span className="text-red-400">No undo.</span> Export a backup first if you want to keep
              anything.
            </p>

            {!confirmingReset ? (
              <button
                onClick={() => setConfirmingReset(true)}
                className="rounded-md border border-red-500/20 bg-red-500/[0.04] px-3 py-1.5 text-xs text-red-400 hover:bg-red-500/10"
              >
                Reset this course…
              </button>
            ) : (
              <div className="rounded-md border border-red-500/30 bg-red-500/10 p-3 text-xs text-red-300">
                <p className="mb-2">Permanently delete everything in this course? There&apos;s no undo.</p>
                <div className="flex gap-2">
                  <button
                    onClick={doReset}
                    disabled={busy}
                    className="rounded border border-red-500/40 bg-red-500/20 px-2 py-1 text-red-200 hover:bg-red-500/30 disabled:cursor-not-allowed disabled:opacity-50"
                  >
                    {resetting ? "Resetting…" : "Yes, empty this course"}
                  </button>
                  <button
                    onClick={() => setConfirmingReset(false)}
                    className="rounded border border-[#423e42] px-2 py-1 text-[#8F8978] hover:bg-[#322f33]"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}
          </div>
          {error && <p role="alert" className="text-xs text-red-400">{error}</p>}
        </div>
      </div>
    </div>
  );
}

import { studyCardKey } from "@/lib/studySession";
